22	
23	fn ind(n: usize) -> String {
24	    " ".repeat(n)
25	}
26	
27	// CSS declarations for one property list, in canonical order.
28	pub fn css_decls(
29	    ctx: &Ctx,
30	    props: &[(String, Value)],
31	    vars: &mut Vec<String>,
32	    stroke_width_ctx: f64,
33	    text: bool,
34	) -> Result<Vec<(String, String)>, Diag> {
35	    let env = &ctx.sheet.env;
36	    let mut out = Vec::new();
37	    for &k in CSS_ORDER {
38	        let v = match get(props, k) {
39	            Some(v) => v,
40	            None => continue,
41	        };
42	        let span = v.span;
43	        match k {
44	            "fill" | "stroke" => {
45	                if let Some(t) = single_term(v) {
46	                    out.push((k.to_string(), color_css(t, vars, span)?));
47	                }
48	            }
49	            "color" => {
50	                if let Some(t) = single_term(v) {
51	                    let name = if text { "fill" } else { "color" };
52	                    out.push((name.to_string(), color_css(t, vars, span)?));
53	                }
54	            }
55	            "stroke-width" | "opacity" => {
56	                if let Some(x) = value_num(env, v) {
57	                    out.push((k.to_string(), f4(x)));
58	                }
59	            }
60	            "font-family" => out.push((k.to_string(), font_family_css(v))),
61	            "font-size" => {
62	                if let Some(x) = value_num(env, v) {
63	                    out.push((k.to_string(), format!("{}px", f4(x))));
64	                }
65	            }
66	            "font-weight" => out.push((k.to_string(), weight_css(v, vars, span)?)),
67	            "font-style" | "text-decoration" => {
68	                if let Some(s) = ident_of(v) {
69	                    out.push((k.to_string(), s.to_string()));
70	                }
71	            }
72	            "text-shadow" => out.push((k.to_string(), text_shadow_css(env, v, vars, span)?)),
73	            "stroke-style" => {
74	                if let Some(s) = ident_of(v) {
75	                    let sw = get(props, "stroke-width").and_then(|w| value_num(env, w)).unwrap_or(stroke_width_ctx);
76	                    if let Some(d) = dasharray(s, sw) {
77	                        out.push(("stroke-dasharray".to_string(), d));
78	                    }
79	                }
80	            }
81	            _ => {}
82	        }
83	    }
84	    Ok(out)
85	}
86	
87	fn join_decls(d: &[(String, String)]) -> String {
88	    d.iter().map(|(k, v)| format!("{}: {}", k, v)).collect::<Vec<_>>().join("; ")
89	}
90	
91	fn font_scale_size(ctx: &Ctx, props: &[(String, Value)]) -> Option<f64> {
92	    let v = get(props, "font-scale")?;
93	    let xs = value_nums(&ctx.sheet.env, v);
94	    if xs.len() == 2 {
95	        Some(xs[0] * ctx.root_font_size / xs[1])
96	    } else {
97	        None
98	    }
99	}
100	
101	// The CSS rule body of one type, from its own defaults plus user rules.
102	fn type_rule_props(ctx: &Ctx, t: &str) -> Vec<(String, Value)> {
103	    let mut props: Vec<(String, Value)> = Vec::new();
104	    let mut set = |k: &str, v: &Value| {
105	        if let Some(e) = props.iter_mut().find(|e| e.0 == k) {
106	            e.1 = v.clone();
107	        } else {
108	            props.push((k.to_string(), v.clone()));
109	        }
110	    };
111	    for d in type_defaults(t) {
112	        set(&d.name, &d.value);
113	    }
114	    if let Some(df) = ctx.sheet.define(t) {
115	        for d in &df.decls {
116	            set(&d.name, &d.value);
117	        }
118	    }
119	    for d in ctx.sheet.type_rule(t) {
120	        set(&d.name, &d.value);
121	    }
122	    props
123	}
124	
125	fn mk_value(t: Term) -> Value {
126	    let sp = t.span();
127	    Value { groups: vec![vec![t]], span: sp }
128	}
129	
130	pub fn render(ctx: &Ctx, opts: &crate::Options) -> Result<String, Diag> {
131	    let mut out = Out { body: String::new(), vars: vec![], used_types: vec![], used_classes: vec![], any_text: false, defs: vec![], markers: false, gutters: false, extra_rules: vec![] };
132	    let root = 0;
133	    // scene body
134	    let mut scene = String::new();
135	    let children = ctx.nodes[root].children.clone();
136	    let ordered = paint_order(ctx, &children);
137	    for ch in ordered {
138	        render_node(ctx, ch, 4, &mut scene, &mut out)?;
139	    }
140	    // stylesheet
141	    let theme = crate::theme::resolve(opts.theme.as_deref().unwrap_or("default")).unwrap();
142	    let mut slots: Vec<(String, String)> = Vec::new();
143	    let type_names: Vec<String> = out.used_types.clone();
144	    for t in &type_names {
145	        let mut props = type_rule_props(ctx, t);
146	        if let Some(sz) = font_scale_size(ctx, &props) {
147	            if get(&props, "font-size").is_none() {
148	                props.push(("font-size".into(), mk_value(Term::Num(sz, f4(sz), Default::default()))));
149	            }
150	        }
151	        let is_prim = types::find(t).map(|d| d.base.is_none()).unwrap_or(false);
152	        if is_prim && get(&props, "stroke-style").is_none() {
153	            props.push(("stroke-style".into(), mk_value(Term::Ident("solid".into(), Default::default()))));
154	        }
155	        let sw = get(&props, "stroke-width").and_then(|w| value_num(&ctx.sheet.env, w)).unwrap_or(2.0);
156	        let decls = css_decls(ctx, &props, &mut out.vars, sw, false)?;
157	        if !decls.is_empty() {
158	            let slot = if types::find(t).is_some() {
159	                t.clone()
160	            } else {
161	                format!("@define:{:04}", ctx.sheet.defines.iter().position(|d| &d.name == t).unwrap_or(0))
162	            };
163	            slots.push((slot, format!(".lini-{} {{ {}; }}", t, join_decls(&decls))));
164	        }
165	    }
166	    if out.any_text {
167	        slots.push(("text".into(), ".lini-text { fill: currentColor; stroke: none; text-anchor: middle; }".to_string()));
168	    }
169	    if out.gutters {
170	        slots.push(("gutter".into(), ".lini-gutter { stroke: none; }".to_string()));
171	    }
172	    if out.markers {
173	        slots.push(("marker".into(), ".lini-marker { fill: var(--lini-stroke); stroke: none; }".to_string()));
174	        use_var(&mut out.vars, "stroke");
175	    }
176	    let canvas_fill = match ctx.sheet.root.iter().rev().find(|d| d.name == "fill") {
177	        Some(d) => match single_term(&d.value) {
178	            Some(t) => Some(color_css(t, &mut out.vars, d.value.span)?),
179	            None => None,
180	        },
181	        None => None,
182	    };
183	    if let Some(f) = &canvas_fill {
184	        slots.push(("canvas".into(), format!(".lini-canvas {{ fill: {}; }}", f)));
185	    }
186	    for (k, c) in ctx.sheet.classes.iter().enumerate() {
187	        if out.used_classes.contains(&c.name) {
188	            let props: Vec<(String, Value)> = c.decls.iter().map(|d| (d.name.clone(), d.value.clone())).collect();
189	            let decls = css_decls(ctx, &props, &mut out.vars, 2.0, false)?;
190	            if !decls.is_empty() {
191	                slots.push((format!("@class:{:04}", k), format!(".lini-style-{} {{ {}; }}", c.name, join_decls(&decls))));
192	            }
193	        }
194	    }
195	    for (slot, rule) in &out.extra_rules {
196	        slots.push((slot.clone(), rule.clone()));
197	    }
198	    slots.sort_by(|a, b| slot_rank(&a.0).cmp(&slot_rank(&b.0)));
199	    let mut rules: Vec<String> = Vec::new();
200	    for (_, r) in slots {
201	        if !rules.contains(&r) {
202	            rules.push(r);
203	        }
204	    }
205	    // root variables
206	    let mut vars = out.vars.clone();
207	    for v in ["fg", "font-family", "font-weight", "text-color"] {
208	        crate::style::use_var(&mut vars, v);
209	    }
210	    let mut decl_vars: Vec<(String, String)> = Vec::new();
211	    let mut k = 0;
212	    while k < vars.len() {
213	        let v = vars[k].clone();
214	        k += 1;
215	        let user = ctx.sheet.vars.iter().rev().find(|d| d.name == v);
216	        let val = if let Some(d) = user {
217	            let mut vv = Vec::new();
218	            let s = value_css_text(ctx, &d.value, &mut vv);
219	            for x in vv {
220	                if !vars.contains(&x) {
221	                    vars.push(x);
222	                }
223	            }
224	            Some(s)
225	        } else {
226	            theme.css_value(&v)
227	        };
228	        if let Some(val) = val {
229	            // nested var() references pull their targets in too
230	            let mut rest = val.as_str();
231	            while let Some(p) = rest.find("var(--lini-") {
232	                let after = &rest[p + 11..];
233	                let end = after.find(')').unwrap_or(after.len());
234	                let name = after[..end].to_string();
235	                if !vars.contains(&name) {
236	                    vars.push(name);
237	                }
238	                rest = &after[end..];
239	            }
240	            decl_vars.push((v, val));
241	        }
242	    }
243	    decl_vars.sort_by(|a, b| a.0.cmp(&b.0));
244	    let mut css = String::new();
245	    css.push_str("    @layer lini.defaults {\n");
246	    let mut root_line = String::from("      :root, .lini {");
247	    if theme.pair {
248	        root_line.push_str(" color-scheme: light dark;");
249	    }
250	    for (k, v) in &decl_vars {
251	        root_line.push_str(&format!(" --lini-{}: {};", k, v));
252	    }
253	    root_line.push_str(" }\n");
254	    css.push_str(&root_line);
255	    if theme.pair {
256	        css.push_str("      .lini[data-theme=\"dark\"], [data-theme=\"dark\"] .lini { color-scheme: dark; }\n");
257	        css.push_str("      .lini[data-theme=\"light\"], [data-theme=\"light\"] .lini { color-scheme: light; }\n");
258	    }
259	    css.push_str("    }\n");
260	    css.push_str("    .lini, .lini text { font-family: var(--lini-font-family); }\n");
261	    css.push_str(&format!(
262	        "    .lini {{ font-size: {}px; font-weight: var(--lini-font-weight); color: var(--lini-text-color); }}\n",
263	        f4(ctx.root_font_size)
264	    ));
265	    for r in &rules {
266	        css.push_str(&format!("    .lini {}\n", r));
267	    }
268	    let hash = hash8(&css);
269	    let scope = format!("lini-scope-{}", hash);
270	    let css_scoped = scope_css(&css, &scope);
271	    // the frame
272	    let (vx, vy, vw, vh) = viewbox(ctx);
273	    let mut s = String::new();
274	    s.push_str(&format!(
275	        "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"{} {} {} {}\" width=\"{}\" height=\"{}\" class=\"lini {}\">\n",
276	        f4(vx),
277	        f4(vy),
278	        f4(vw),
279	        f4(vh),
280	        f4(vw),
281	        f4(vh),
282	        scope
283	    ));
284	    s.push_str("  <style>\n");
285	    s.push_str(&css_scoped);
286	    s.push_str("  </style>\n");
287	    if out.defs.is_empty() {
288	        s.push_str("  <defs/>\n");
289	    } else {
290	        s.push_str("  <defs>\n");
291	        for d in &out.defs {
292	            s.push_str(&format!("    {}\n", d));
293	        }
294	        s.push_str("  </defs>\n");
295	    }
296	    if canvas_fill.is_some() {
297	        s.push_str(&format!(
298	            "  <rect class=\"lini-canvas\" x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\"/>\n",
299	            f4(vx),
300	            f4(vy),
301	            f4(vw),
302	            f4(vh)
303	        ));
304	    }
305	    s.push_str("  <g class=\"lini-scene\">\n");
306	    s.push_str(&scene);
307	    s.push_str("  </g>\n");
308	    s.push_str("  <g class=\"lini-links\"/>\n");
309	    s.push_str("</svg>\n");
310	    Ok(s)
311	}
312	
313	fn scope_css(css: &str, scope: &str) -> String {
314	    // replace the '.lini' scope selector (not '.lini-xxx' classes)
315	    let mut o = String::new();
316	    let b = css.as_bytes();
317	    let mut i = 0;
318	    while i < b.len() {
319	        if css[i..].starts_with(".lini") {
320	            let next = b.get(i + 5).copied().unwrap_or(b' ');
321	            if next != b'-' {
322	                o.push('.');
323	                o.push_str(scope);
324	                i += 5;
325	                continue;
326	            }
327	        }
328	        let ch = css[i..].chars().next().unwrap();
329	        o.push(ch);
330	        i += ch.len_utf8();
331	    }
332	    o
333	}
334	
335	pub fn value_css_text(ctx: &Ctx, v: &Value, vars: &mut Vec<String>) -> String {
336	    let mut parts = Vec::new();
337	    for g in &v.groups {
338	        let mut gp = Vec::new();
339	        for t in g {
340	            match t {
341	                Term::Num(x, _, _) => gp.push(f4(*x)),
342	                Term::Var(n, _) => {
343	                    use_var(vars, n);
344	                    gp.push(format!("var(--lini-{})", n));
345	                }
346	                Term::Hash(h, _) => gp.push(format!("#{}", h)),
347	                Term::Ident(n, _) => gp.push(n.clone()),
348	                Term::Str(s, _) => gp.push(format!("\"{}\"", s)),
349	                _ => {
350	                    if let Ok(c) = color_css(t, vars, v.span) {
351	                        gp.push(c);
352	                    }
353	                }
354	            }
355	        }
356	        parts.push(gp.join(" "));
357	    }
358	    let _ = ctx;
359	    parts.join(", ")
360	}
