866	// Stylesheet rule order. Type rules use their type name as the slot; user
867	// defines and classes use "@define:NNNN" / "@class:NNNN".
868	pub static SLOT_ORDER: &[&str] = &[
869	    "canvas",
870	    "block", "oval", "hex", "slant", "cyl", "diamond", "poly", "path", "sketch", "line", "text", "icon", "image",
871	    "chart-text", "gutter",
872	    "box", "rect", "group", "row", "column", "grid", "caption", "footnote", "badge", "table", "cell", "header", "entity",
873	    "sign", "note", "topic", "mindmap", "chart", "bars", "area", "dots", "bubble", "band", "mark", "axis", "pie", "slice",
874	    "sequence", "loop", "alt", "opt", "else", "stack", "drawing", "floorplan", "hole", "hidden", "centerline",
875	    "pitch-circle", "plane", "magnifier", "feature-control", "datum", "surface-finish", "balloon", "page", "title-block",
876	    "frame", "zone", "tick", "field", "wall", "partition", "door", "window", "stairs", "bed", "sofa", "dining",
877	    "appliance", "bath", "schematic", "sch-line", "ref", "component", "pin", "space", "label",
878	    "@define",
879	    "link", "link-label", "cut-bg", "cut", "marker", "link-marker",
880	    "@class",
881	];
882	
883	pub fn slot_rank(slot: &str) -> (usize, String) {
884	    if let Some(rest) = slot.strip_prefix("@define:") {
885	        let p = SLOT_ORDER.iter().position(|s| *s == "@define").unwrap();
886	        return (p, rest.to_string());
887	    }
888	    if let Some(rest) = slot.strip_prefix("@class:") {
889	        let p = SLOT_ORDER.iter().position(|s| *s == "@class").unwrap();
890	        return (p, rest.to_string());
891	    }
892	    match SLOT_ORDER.iter().position(|s| *s == slot) {
893	        Some(p) => (p, String::new()),
894	        None => (SLOT_ORDER.len(), slot.to_string()),
895	    }
896	}
