7	pub fn outer(ctx: &Ctx, i: usize) -> (f64, f64) {
8	    let n = &ctx.nodes[i];
9	    let c = &ctx.comp[i];
10	    if n.prim == Prim::Text {
11	        return (n.w, n.h);
12	    }
13	    let s = if c.has_stroke { c.stroke_width } else { 0.0 };
14	    (n.w + s, n.h + s)
15	}
