17	pub fn transform_text(s: &str, tt: &Option<String>) -> String {
18	    match tt.as_deref() {
19	        Some("uppercase") => s.to_uppercase(),
20	        Some("lowercase") => s.to_lowercase(),
21	        Some("capitalize") => {
22	            let mut out = String::new();
23	            let mut start = true;
24	            for ch in s.chars() {
25	                if start && ch.is_alphabetic() {
26	                    out.extend(ch.to_uppercase());
27	                    start = false;
28	                } else {
29	                    out.push(ch);
30	                    if ch.is_whitespace() {
31	                        start = true;
32	                    } else {
33	                        start = false;
34	                    }
35	                }
36	            }
37	            out
38	        }
39	        _ => s.to_string(),
40	    }
41	}
