127	#[derive(Clone, Debug)]
128	pub enum Track {
129	    Auto,
130	    Fixed(f64),
131	}
132	
133	pub fn parse_tracks(ctx: &Ctx, v: &crate::ast::Value) -> Vec<Track> {
134	    use crate::ast::{Expr, Term};
135	    let env = &ctx.sheet.env;
136	    let mut out = Vec::new();
137	    for g in &v.groups {
138	        for t in g {
139	            match t {
140	                Term::Ident(s, _) if s == "auto" => out.push(Track::Auto),
141	                Term::Call(name, args, _) if name == "repeat" => {
142	                    let n = args.first().and_then(|a| env.eval(a, &Default::default()).ok()).and_then(|x| x.num()).unwrap_or(1.0) as usize;
143	                    let tr = match args.get(1) {
144	                        Some(Expr::Ident(s, _)) if s == "auto" => Track::Auto,
145	                        Some(a) => match env.eval(a, &Default::default()).ok().and_then(|x| x.num()) {
146	                            Some(x) => Track::Fixed(x),
147	                            None => Track::Auto,
148	                        },
149	                        None => Track::Auto,
150	                    };
151	                    for _ in 0..n {
152	                        out.push(tr.clone());
153	                    }
154	                }
155	                _ => {
156	                    if let Some(x) = crate::style::term_num(env, t) {
157	                        out.push(Track::Fixed(x));
158	                    }
159	                }
160	            }
161	        }
162	    }
163	    out
164	}
