364	pub fn measure_flow(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
365	    let c = ctx.comp[i].clone();
366	    let pad = c.padding;
367	    let mut inner_avail = avail.map(|a| a - pad[1] - pad[3]);
368	    if let Some(m) = c.max_width {
369	        let a = m - pad[1] - pad[3];
370	        inner_avail = Some(inner_avail.map_or(a, |x: f64| x.min(a)));
371	    }
372	    let children = ctx.nodes[i].children.clone();
373	    let mut flow = Vec::new();
374	    let mut pinned = Vec::new();
375	    for &ch in &children {
376	        if ctx.comp[ch].pin.is_some() {
377	            pinned.push(ch);
378	        } else {
379	            flow.push(ch);
380	        }
381	    }
382	    for &ch in &children {
383	        measure(ctx, ch, if ctx.comp[ch].pin.is_some() { None } else { inner_avail });
384	    }
385	    let sizes: Vec<(f64, f64)> = flow.iter().map(|&ch| outer(ctx, ch)).collect();
386	    let (gap_main, row) = match c.direction {
387	        Dir::Row => (c.gap.1, true),
388	        Dir::Column => (c.gap.0, false),
389	    };
390	    let n = sizes.len();
391	    let mut main: f64 = 0.0;
392	    let mut cross: f64 = 0.0;
393	    for &(w, h) in &sizes {
394	        if row {
395	            main += w;
396	            cross = cross.max(h);
397	        } else {
398	            main += h;
399	            cross = cross.max(w);
400	        }
401	    }
402	    if n > 1 {
403	        main += gap_main * (n as f64 - 1.0);
404	    }
405	    let (cw, ch) = if row { (main, cross) } else { (cross, main) };
406	    let mut w = cw + pad[1] + pad[3];
407	    let mut h = ch + pad[0] + pad[2];
408	    if let Some(fw) = c.width {
409	        w = w.max(fw);
410	    }
411	    if let Some(fh) = c.height {
412	        h = h.max(fh);
413	    }
414	    ctx.nodes[i].w = w;
415	    ctx.nodes[i].h = h;
416	    // place flow children
417	    let inner_l = -w / 2.0 + pad[3];
418	    let inner_t = -h / 2.0 + pad[0];
419	    let inner_w = w - pad[1] - pad[3];
420	    let inner_h = h - pad[0] - pad[2];
421	    let free = if row { inner_w - main } else { inner_h - main };
422	    let start = match c.justify {
423	        Align::Start | Align::Stretch => 0.0,
424	        Align::Center => free / 2.0,
425	        Align::End => free,
426	    };
427	    let mut cursor = start;
428	    for (k, &chi) in flow.iter().enumerate() {
429	        let (ow, oh) = sizes[k];
430	        if row {
431	            let x = inner_l + cursor + ow / 2.0;
432	            let y = match c.align {
433	                Align::Start => inner_t + oh / 2.0,
434	                Align::End => inner_t + inner_h - oh / 2.0,
435	                _ => inner_t + inner_h / 2.0,
436	            };
437	            ctx.nodes[chi].x = x;
438	            ctx.nodes[chi].y = y;
439	            cursor += ow + gap_main;
440	        } else {
441	            let y = inner_t + cursor + oh / 2.0;
442	            let x = match c.align {
443	                Align::Start => inner_l + ow / 2.0,
444	                Align::End => inner_l + inner_w - ow / 2.0,
445	                _ => inner_l + inner_w / 2.0,
446	            };
447	            ctx.nodes[chi].x = x;
448	            ctx.nodes[chi].y = y;
449	            cursor += oh + gap_main;
450	        }
451	    }
452	    if ctx.nodes[i].props.contains_key("gap-fill") && n > 1 && gap_main > 0.0 {
453	        let mut g = Vec::new();
454	        let mut cur = start;
455	        for k in 0..n - 1 {
456	            let (ow, oh) = sizes[k];
457	            cur += if row { ow } else { oh };
458	            if row {
459	                g.push((inner_l + cur, -h / 2.0, gap_main, h));
460	            } else {
461	                g.push((-w / 2.0, inner_t + cur, w, gap_main));
462	            }
463	            cur += gap_main;
464	        }
465	        ctx.nodes[i].gutters = g;
466	    }
467	    if ctx.nodes[i].prim == Prim::Cyl {
468	        let (_, oh) = outer(ctx, i);
469	        let dy = 0.03 * oh;
470	        for &chi in &flow {
471	            ctx.nodes[chi].y += dy;
472	        }
473	    }
474	    for &p in &pinned {
475	        place_pinned(ctx, i, p);
476	    }
477	}
478	
479	pub fn place_pinned(ctx: &mut Ctx, parent: usize, i: usize) {
480	    let pin = ctx.comp[i].pin.clone().unwrap_or_default();
481	    let pw = ctx.nodes[parent].w;
482	    let ph = ctx.nodes[parent].h;
483	    let (cw, chh) = outer(ctx, i);
484	    let words: Vec<&str> = pin.split_whitespace().collect();
485	    let mut x = 0.0;
486	    let mut y = 0.0;
487	    for w in &words {
488	        match *w {
489	            "top" => y = -ph / 2.0 + chh / 2.0,
490	            "bottom" => y = ph / 2.0 - chh / 2.0,
491	            "left" => x = -pw / 2.0 + cw / 2.0,
492	            "right" => x = pw / 2.0 - cw / 2.0,
493	            _ => {}
494	        }
495	    }
496	    ctx.nodes[i].x = x;
497	    ctx.nodes[i].y = y;
498	}
499	
500	pub fn eval_points(ctx: &Ctx, i: usize) -> Vec<(f64, f64)> {
501	    use crate::ast::Term;
502	    use crate::eval::EV;
503	    let env = &ctx.sheet.env;
504	    let v = match ctx.nodes[i].props.get("points") {
505	        Some(v) => v.clone(),
506	        None => return vec![],
507	    };
508	    let samples = ctx.nodes[i].props.get("samples").and_then(|s| crate::style::value_num(env, s)).unwrap_or(2.0).max(2.0) as usize;
509	    let mut pts = Vec::new();
510	    for g in &v.groups {
511	        let nums: Vec<f64> = g.iter().filter_map(|t| crate::style::term_num(env, t)).collect();
512	        if g.len() == 2 && nums.len() == 2 {
513	            pts.push((nums[0], nums[1]));
514	            continue;
515	        }
516	        if g.len() == 1 {
517	            // a parametric point: sample u over [0, 1]
518	            let t = &g[0];
519	            for k in 0..samples {
520	                let u = k as f64 / (samples as f64 - 1.0);
521	                let mut locals = std::collections::HashMap::new();
522	                locals.insert("u".to_string(), EV::Num(u));
523	                let r = match t {
524	                    Term::Group(e, _) => env.eval(e, &locals),
525	                    Term::Call(..) => env.eval_term(t, &locals),
526	                    _ => continue,
527	                };
528	                if let Ok(EV::Tuple(xs)) = r {
529	                    if xs.len() >= 2 {
530	                        pts.push((xs[0].num().unwrap_or(0.0), xs[1].num().unwrap_or(0.0)));
531	                    }
532	                }
533	            }
534	        }
535	    }
536	    pts
537	}
538	
539	pub fn measure_geo(ctx: &mut Ctx, i: usize) {
540	    use crate::geom::{path_bbox, BBox};
541	    use crate::scene::Geo;
542	    let prim = ctx.nodes[i].prim;
543	    let mut bb = BBox::empty();
544	    let geo = if prim == Prim::Path {
545	        let d = match ctx.nodes[i].props.get("path").and_then(crate::style::single_term) {
546	            Some(crate::ast::Term::Str(s, _)) => s.clone(),
547	            _ => String::new(),
548	        };
549	        bb = path_bbox(&d);
550	        Geo::Path(d)
551	    } else {
552	        let pts = eval_points(ctx, i);
553	        for &(x, y) in &pts {
554	            bb.add(x, y);
555	        }
556	        Geo::Points(pts)
557	    };
558	    let n = &mut ctx.nodes[i];
559	    n.w = bb.w();
560	    n.h = bb.h();
561	    n.geo_off = (-bb.cx(), -bb.cy());
562	    n.geo = Some(geo);
563	}
