149	fn parse_align(s: &str) -> Option<Align> {
150	    match s {
151	        "start" | "top" | "left" => Some(Align::Start),
152	        "center" | "middle" => Some(Align::Center),
153	        "end" | "bottom" | "right" => Some(Align::End),
154	        "stretch" => Some(Align::Stretch),
155	        _ => None,
156	    }
157	}
