110	pub fn measure(ctx: &mut Ctx, i: usize, avail: Option<f64>) {
111	    let prim = ctx.nodes[i].prim;
112	    match prim {
113	        Prim::Text => measure_text(ctx, i, avail),
114	        Prim::Line | Prim::Poly | Prim::Path => measure_geo(ctx, i),
115	        _ => {
116	            if crate::chart::is_chart(ctx, i) {
117	                crate::chart::measure(ctx, i)
118	            } else if ctx.comp[i].layout == "grid" {
119	                measure_grid(ctx, i, avail)
120	            } else {
121	                measure_flow(ctx, i, avail)
122	            }
123	        }
124	    }
125	}
