500	pub fn eval_points(ctx: &Ctx, i: usize) -> Vec<(f64, f64)> {
501	    use crate::ast::Term;
502	    use crate::eval::EV;
503	    let env = &ctx.sheet.env;
504	    let v = match ctx.nodes[i].props.get("points") {
505	        Some(v) => v.clone(),
506	        None => return vec![],
507	    };
508	    let samples = ctx.nodes[i].props.get("samples").and_then(|s| crate::style::value_num(env, s)).unwrap_or(2.0).max(2.0) as usize;
509	    let mut pts = Vec::new();
510	    for g in &v.groups {
511	        let nums: Vec<f64> = g.iter().filter_map(|t| crate::style::term_num(env, t)).collect();
512	        if g.len() == 2 && nums.len() == 2 {
513	            pts.push((nums[0], nums[1]));
514	            continue;
515	        }
516	        if g.len() == 1 {
517	            // a parametric point: sample u over [0, 1]
518	            let t = &g[0];
519	            for k in 0..samples {
520	                let u = k as f64 / (samples as f64 - 1.0);
521	                let mut locals = std::collections::HashMap::new();
522	                locals.insert("u".to_string(), EV::Num(u));
523	                let r = match t {
524	                    Term::Group(e, _) => env.eval(e, &locals),
525	                    Term::Call(..) => env.eval_term(t, &locals),
526	                    _ => continue,
527	                };
528	                if let Ok(EV::Tuple(xs)) = r {
529	                    if xs.len() >= 2 {
530	                        pts.push((xs[0].num().unwrap_or(0.0), xs[1].num().unwrap_or(0.0)));
531	                    }
532	                }
533	            }
534	        }
535	    }
536	    pts
537	}
