539	pub fn measure_geo(ctx: &mut Ctx, i: usize) {
540	    use crate::geom::{path_bbox, BBox};
541	    use crate::scene::Geo;
542	    let prim = ctx.nodes[i].prim;
543	    let mut bb = BBox::empty();
544	    let geo = if prim == Prim::Path {
545	        let d = match ctx.nodes[i].props.get("path").and_then(crate::style::single_term) {
546	            Some(crate::ast::Term::Str(s, _)) => s.clone(),
547	            _ => String::new(),
548	        };
549	        bb = path_bbox(&d);
550	        Geo::Path(d)
551	    } else {
552	        let pts = eval_points(ctx, i);
553	        for &(x, y) in &pts {
554	            bb.add(x, y);
555	        }
556	        Geo::Points(pts)
557	    };
558	    let n = &mut ctx.nodes[i];
559	    n.w = bb.w();
560	    n.h = bb.h();
561	    n.geo_off = (-bb.cx(), -bb.cy());
562	    n.geo = Some(geo);
563	}
