159	pub fn compute(ctx: &mut Ctx) {
160	    let n = ctx.nodes.len();
161	    ctx.comp = vec![Computed::default(); n];
162	    // nodes are created parent-before-child, so a forward pass sees parents first
163	    for i in 0..n {
164	        let parent = ctx.nodes[i].parent;
165	        let pc = parent.map(|p| ctx.comp[p].clone());
166	        let (_, props) = if i == 0 { (vec![], ctx.nodes[0].inline.iter().map(|d| (d.name.clone(), d.value.clone())).collect()) } else { cascade(&ctx.sheet, &ctx.nodes[i]) };
167	        let env = &ctx.sheet.env;
168	        let mut c = Computed::default();
169	        if let Some(p) = &pc {
170	            c.font_size = p.font_size;
171	            c.font_weight = p.font_weight;
172	            c.family = p.family;
173	            c.letter_spacing = p.letter_spacing;
174	            c.line_spacing = p.line_spacing;
175	            c.text_transform = p.text_transform.clone();
176	            c.family_css = p.family_css.clone();
177	        }
178	        let num = |k: &str| get(&props, k).and_then(|v| value_num(env, v));
179	        if let Some(v) = num("font-size") {
180	            c.font_size = v;
181	        } else if let Some(v) = get(&props, "font-scale") {
182	            let xs = value_nums(env, v);
183	            if xs.len() == 2 {
184	                let base = pc.as_ref().map(|p| p.font_size).unwrap_or(15.0);
185	                c.font_size = xs[0] * base / xs[1];
186	            }
187	        }
188	        if let Some(v) = get(&props, "font-weight") {
189	            c.font_weight = weight_num(v);
190	        }
191	        if let Some(v) = get(&props, "font-family") {
192	            c.family = family_of(v);
193	            c.family_css = Some(font_family_css(v));
194	        }
195	        if let Some(v) = num("letter-spacing") {
196	            c.letter_spacing = v;
197	        }
198	        if let Some(v) = num("line-spacing") {
199	            c.line_spacing = v;
200	        }
201	        if let Some(v) = get(&props, "text-transform") {
202	            c.text_transform = ident_of(v).map(|s| s.to_string());
203	        }
204	        if let Some(v) = get(&props, "padding") {
205	            let xs = value_nums(env, v);
206	            c.padding = match xs.len() {
207	                1 => [xs[0]; 4],
208	                2 => [xs[0], xs[1], xs[0], xs[1]],
209	                4 => [xs[0], xs[1], xs[2], xs[3]],
210	                _ => [0.0; 4],
211	            };
212	        }
213	        if let Some(v) = get(&props, "gap") {
214	            let xs = value_nums(env, v);
215	            c.gap = match xs.len() {
216	                1 => (xs[0], xs[0]),
217	                2 => (xs[0], xs[1]),
218	                _ => c.gap,
219	            };
220	        }
221	        if let Some(v) = get(&props, "direction") {
222	            if ident_of(v) == Some("column") {
223	                c.direction = Dir::Column;
224	            }
225	        }
226	        if let Some(v) = get(&props, "align") {
227	            if let Some(a) = ident_of(v).and_then(parse_align) {
228	                c.align = a;
229	            }
230	        }
231	        if let Some(v) = get(&props, "justify") {
232	            if let Some(a) = ident_of(v).and_then(parse_align) {
233	                c.justify = a;
234	            }
235	        }
236	        c.width = num("width");
237	        c.height = num("height");
238	        c.max_width = num("max-width");
239	        if let Some(v) = num("stroke-width") {
240	            c.stroke_width = v;
241	        }
242	        if let Some(v) = get(&props, "stroke") {
243	            c.has_stroke = ident_of(v) != Some("none");
244	        }
245	        if let Some(v) = num("radius") {
246	            c.radius = v;
247	        }
248	        if let Some(v) = get(&props, "pin") {
249	            let mut parts = Vec::new();
250	            for g in &v.groups {
251	                for t in g {
252	                    if let Term::Ident(s, _) = t {
253	                        parts.push(s.clone());
254	                    }
255	                }
256	            }
257	            c.pin = Some(parts.join(" "));
258	        }
259	        if let Some(v) = get(&props, "translate") {
260	            let xs = value_nums(env, v);
261	            if xs.len() == 2 {
262	                c.translate = (xs[0], xs[1]);
263	            }
264	        }
265	        if let Some(v) = num("rotate") {
266	            c.rotate = v;
267	        }
268	        if let Some(v) = get(&props, "layout") {
269	            if let Some(s) = ident_of(v) {
270	                c.layout = s.to_string();
271	            }
272	        }
273	        if let Some(v) = get(&props, "text-wrap") {
274	            c.nowrap = ident_of(v) == Some("nowrap");
275	        }
276	        ctx.nodes[i].props = props.into_iter().collect();
277	        ctx.comp[i] = c;
278	    }
279	}
