151	pub fn build_sheet(doc: &Doc) -> Result<SheetModel, Diag> {
152	    let mut m = SheetModel::default();
153	    if let Some(sheet) = &doc.sheet {
154	        for item in &sheet.items {
155	            match item {
156	                SheetItem::Decl(d) => m.root.push(d.clone()),
157	                SheetItem::Var(d) => m.vars.push(d.clone()),
158	                SheetItem::Binding(b) => {
159	                    if let Some(params) = &b.params {
160	                        m.env.funcs.insert(b.name.clone(), Func { params: params.clone(), body: b.expr.clone() });
161	                    } else {
162	                        let v = m.env.eval_term(&b.expr, &HashMap::new())?;
163	                        m.env.vars.insert(b.name.clone(), v);
164	                    }
165	                }
166	                SheetItem::Rule(r) => {
167	                    // classify selector
168	                    if r.selector.len() == 1 {
169	                        let c = &r.selector[0];
170	                        if c.bars && c.type_name.as_deref() == Some("-") && c.id.is_none() && c.classes.is_empty() {
171	                            m.link_rules.extend(r.decls.iter().cloned());
172	                            continue;
173	                        }
174	                        if c.bars && c.id.is_none() && c.classes.is_empty() {
175	                            if let Some(t) = &c.type_name {
176	                                m.type_rules.push((t.clone(), r.decls.clone()));
177	                                continue;
178	                            }
179	                        }
180	                        if !c.bars && c.id.is_none() && c.classes.len() == 1 {
181	                            m.classes.push(ClassRule { name: c.classes[0].clone(), decls: r.decls.clone(), span: r.span, used: false });
182	                            continue;
183	                        }
184	                        if c.id.is_some() && c.classes.is_empty() {
185	                            m.id_rules.push((c.id.clone().unwrap(), r.decls.clone()));
186	                            continue;
187	                        }
188	                    }
189	                    if r.selector.len() == 2 {
190	                        let a = &r.selector[0];
191	                        let b = &r.selector[1];
192	                        if a.id.is_some() && !a.bars && b.bars && b.type_name.as_deref() == Some("-") {
193	                            m.scoped_link_rules.push((a.id.clone().unwrap(), r.decls.clone()));
194	                            continue;
195	                        }
196	                    }
197	                }
198	                SheetItem::Define(d) => {
199	                    m.defines.push(DefineModel {
200	                        name: d.name.clone(),
201	                        base: d.base.clone(),
202	                        decls: d.decls.clone(),
203	                        body: d.body.clone(),
204	                        span: d.span,
205	                    });
206	                }
207	            }
208	        }
209	    }
210	    Ok(m)
211	}
