pub fn is_named_color(s: &str) -> bool {
    let l = s.to_ascii_lowercase();
    NAMED_COLORS.contains(&l.as_str())
}

pub fn valid_hex(h: &str) -> bool {
    matches!(h.len(), 3 | 4 | 6 | 8) && h.chars().all(|c| c.is_ascii_hexdigit())
}

// Serialise an expression argument of a colour function.
fn expr_text(e: &Expr) -> String {
    match e {
        Expr::Num(v, _) => f4(*v),
        Expr::Percent(v, _) => format!("{}%", f4(*v)),
        Expr::Ident(n, _) => n.clone(),
        Expr::Unary(op, a, _) => format!("{}{}", op, expr_text(a)),
        _ => String::new(),
    }
}

pub struct CssCtx<'a> {
    pub env: &'a Env,
    pub vars_used: &'a mut Vec<String>,
}

pub fn use_var(vars_used: &mut Vec<String>, name: &str) {
    if !vars_used.iter().any(|v| v == name) {
        vars_used.push(name.to_string());
    }
}

// A colour term → CSS text. Errors carry the declaration span.
pub fn color_css(t: &Term, vars_used: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    match t {
        Term::Var(v, _) => {
            use_var(vars_used, v);
            Ok(format!("var(--lini-{})", v))
        }
        Term::Hash(h, sp) => {
            if !valid_hex(h) {
                return Err(Diag::error("parse", &format!("invalid hex color '#{}'", h), *sp));
            }
            Ok(format!("#{}", h))
        }
        Term::Ident(n, _) => {
            if is_named_color(n) {
                Ok(n.clone())
            } else {
                Err(Diag::error("invalid-color", &format!("invalid color '{}'", n), span))
            }
        }
        Term::Str(s, _) => Ok(format!("\"{}\"", s)),
        Term::Call(name, args, _) => match name.as_str() {
            "rgb" | "rgba" | "hsl" | "hsla" => {
                let parts: Vec<String> = args.iter().map(expr_text).collect();
                Ok(format!("{}({})", name, parts.join(", ")))
            }
            "oklch" => {
                let nums: Vec<f64> = args
                    .iter()
                    .map(|a| match a {
                        Expr::Num(v, _) => *v,
                        Expr::Unary(o, b, _) if o == "-" => match &**b {
                            Expr::Num(v, _) => -*v,
                            _ => f64::NAN,
                        },
                        _ => f64::NAN,
                    })
                    .collect();
                if (nums.len() != 3 && nums.len() != 4) || nums.iter().any(|x| x.is_nan()) {
                    return Err(Diag::error(
                        "malformed-value",
                        "oklch expects (L, C, H) or (L, C, H, A) — L and A in 0..1, C ≥ 0, H in degrees",
                        span,
                    ));
                }
                Ok(crate::color::oklch_hex(nums[0], nums[1], nums[2], nums.get(3).copied()))
            }
            _ => Err(Diag::error("invalid-color", &format!("invalid color '{}'", name), span)),
        },
        _ => Err(Diag::error("invalid-color", "invalid color", span)),
    }
}

pub fn weight_css(v: &Value, vars_used: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    let bad = || {
        Diag::error(
            "malformed-value",
            "'font-weight' takes normal, medium, semibold, bold, or 400, 500, 600, 700",
            span,
        )
    };
    match single_term(v) {
        Some(Term::Ident(n, _)) => Ok(match n.as_str() {
            "normal" => "normal".into(),
            "bold" => "bold".into(),
            "medium" => "500".into(),
            "semibold" => "600".into(),
            "light" => "normal".into(),
            _ => return Err(bad()),
        }),
        Some(Term::Num(x, _, _)) => {
            if [400.0, 500.0, 600.0, 700.0].contains(x) {
                Ok(f4(*x))
            } else {
                Err(bad())
            }
        }
        Some(Term::Var(n, _)) => {
            use_var(vars_used, n);
            Ok(format!("var(--lini-{})", n))
        }
        _ => Err(bad()),
    }
}

// Numeric weight for metrics (vars resolve to their theme value).
pub fn weight_num(v: &Value) -> u32 {
    match single_term(v) {
        Some(Term::Ident(n, _)) => match n.as_str() {
            "bold" => 700,
            "semibold" => 600,
            "medium" => 500,
            _ => 400,
        },
        Some(Term::Num(x, _, _)) => *x as u32,
        Some(Term::Var(n, _)) => match n.as_str() {
            "caption-font-weight" | "link-font-weight" => 400,
            "font-weight" => 500,
            _ => 500,
        },
        _ => 500,
    }
}

pub fn dasharray(style: &str, sw: f64) -> Option<String> {
    match style {
        "solid" => Some("none".into()),
        "dashed" => Some(format!("{},{}", f4(2.0 * sw + 3.0), f4(1.5 * sw + 2.5))),
        "dotted" => Some(format!("{},{}", f4(sw), f4(1.5 * sw))),
        "center" => {
            let g = f4(1.5 * sw + 1.5);
            Some(format!("{},{},{},{}", f4(5.0 * sw + 5.0), g, f4(sw), g))
        }
        "phantom" => {
            let g = f4(1.5 * sw + 1.5);
            Some(format!("{},{},{},{},{},{}", f4(5.0 * sw + 5.0), g, f4(sw), g, f4(sw), g))
        }
        _ => None,
    }
}

pub fn text_shadow_css(env: &Env, v: &Value, vars_used: &mut Vec<String>, span: Span) -> Result<String, Diag> {
    let mut parts = Vec::new();
    for g in &v.groups {
        let mut gp = Vec::new();
        for t in g {
            match t {
                Term::Num(..) | Term::Group(..) => {
                    let x = term_num(env, t).unwrap_or(0.0);
                    gp.push(format!("{}px", f4(x)));
                }
                _ => gp.push(color_css(t, vars_used, span)?),
            }
        }
        parts.push(gp.join(" "));
    }
    Ok(parts.join(", "))
}

pub fn font_family_css(v: &Value) -> String {
    let mut parts = Vec::new();
    for g in &v.groups {
        let mut gp = Vec::new();
        for t in g {
            match t {
                Term::Str(s, _) => gp.push(format!("\"{}\"", s)),
                Term::Ident(s, _) => gp.push(s.clone()),
                _ => {}
            }
        }
        parts.push(gp.join(" "));
    }
    parts.join(", ")
}

pub fn family_of(v: &Value) -> crate::font::Family {
    let mut s = String::new();
    for g in &v.groups {
        for t in g {
            match t {
                Term::Str(x, _) | Term::Ident(x, _) => {
                    s = x.to_ascii_lowercase();
                }
                _ => {}
            }
        }
        break;
    }
    if s.contains("mono") || s.contains("code") || s == "monospace" {
        crate::font::Family::Code
    } else {
        crate::font::Family::Sans
    }
}
// Small shared helpers: number formatting, escaping, hashing.

// Numbers print with at most four decimals, trailing zeros trimmed.
pub fn f4(v: f64) -> String {
    let mut s = format!("{:.4}", v);
    if s.contains('.') {
        while s.ends_with('0') {
            s.pop();
        }
        if s.ends_with('.') {
            s.pop();
        }
    }
    if s == "-0" {
        s = "0".to_string();
    }
    s
}

// Rust's default float Display (shortest round-trip), used by a few raw paths.
pub fn fraw(v: f64) -> String {
    if v == 0.0 {
        return "0".to_string();
    }
    format!("{}", v)
}

pub fn xml_escape(s: &str) -> String {
    let mut o = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => o.push_str("&amp;"),
            '<' => o.push_str("&lt;"),
            '>' => o.push_str("&gt;"),
            '"' => o.push_str("&quot;"),
            _ => o.push(c),
        }
    }
    o
}

pub fn fnv1a64(data: &[u8]) -> u64 {
    let mut h: u64 = 0xcbf29ce484222325;
    for &b in data {
        h ^= b as u64;
        h = h.wrapping_mul(0x100000001b3);
    }
    h
}

pub fn fold32(h: u64) -> u32 {
    ((h >> 32) as u32) ^ (h as u32)
}

pub fn hash8(s: &str) -> String {
    format!("{:08x}", fold32(fnv1a64(s.as_bytes())))
}

// Levenshtein distance for "did you mean" suggestions.
pub fn levenshtein(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

pub fn base64(data: &[u8]) -> String {
    const T: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut o = String::with_capacity((data.len() + 2) / 3 * 4);
    for chunk in data.chunks(3) {
        let b0 = chunk[0] as u32;
        let b1 = if chunk.len() > 1 { chunk[1] as u32 } else { 0 };
        let b2 = if chunk.len() > 2 { chunk[2] as u32 } else { 0 };
        let n = (b0 << 16) | (b1 << 8) | b2;
        o.push(T[((n >> 18) & 63) as usize] as char);
        o.push(T[((n >> 12) & 63) as usize] as char);
        if chunk.len() > 1 {
            o.push(T[((n >> 6) & 63) as usize] as char);
        } else {
            o.push('=');
        }
        if chunk.len() > 2 {
            o.push(T[(n & 63) as usize] as char);
        } else {
            o.push('=');
        }
    }
    o
}
// Compile-time expression evaluation: bindings, functions, math.

use crate::ast::{Expr, Term};
use crate::diag::{Diag, Span};
use std::collections::HashMap;

#[derive(Debug, Clone, PartialEq)]
pub enum EV {
    Num(f64),
    Tuple(Vec<EV>),
    Str(String),
}

impl EV {
    pub fn num(&self) -> Option<f64> {
        match self {
            EV::Num(v) => Some(*v),
            _ => None,
        }
    }
}

#[derive(Clone, Debug)]
pub struct Func {
    pub params: Vec<String>,
    pub body: Term,
}

#[derive(Default, Clone, Debug)]
pub struct Env {
    pub vars: HashMap<String, EV>,
    pub funcs: HashMap<String, Func>,
}

pub fn err(msg: &str, span: Span) -> Diag {
    Diag::error("resolve", msg, span)
}

impl Env {
    pub fn eval_term(&self, t: &Term, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match t {
            Term::Num(v, _, _) => Ok(EV::Num(*v)),
            Term::Group(e, _) => self.eval(e, locals),
            Term::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Term::Ident(n, sp) => self.lookup(n, locals, *sp),
            Term::Str(s, _) => Ok(EV::Str(s.clone())),
            _ => Err(err("expected a number", t.span())),
        }
    }

    fn lookup(&self, n: &str, locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(v) = locals.get(n) {
            return Ok(v.clone());
        }
        if let Some(v) = self.vars.get(n) {
            return Ok(v.clone());
        }
        match n {
            "pi" => Ok(EV::Num(std::f64::consts::PI)),
            "e" => Ok(EV::Num(std::f64::consts::E)),
            _ => Err(err(&format!("unknown name '{}' in an expression", n), sp)),
        }
    }

    pub fn eval(&self, e: &Expr, locals: &HashMap<String, EV>) -> Result<EV, Diag> {
        match e {
            Expr::Num(v, _) => Ok(EV::Num(*v)),
            Expr::Percent(v, _) => Ok(EV::Num(*v / 100.0)),
            Expr::Str(s, _) => Ok(EV::Str(s.clone())),
            Expr::Ident(n, sp) => self.lookup(n, locals, *sp),
            Expr::Var(_, sp) | Expr::Hash(_, sp) => Err(err("expected a number", *sp)),
            Expr::Call(name, args, sp) => self.call(name, args, locals, *sp),
            Expr::Unary(op, a, sp) => {
                let v = self.eval(a, locals)?;
                let x = v.num().ok_or_else(|| err("expected a number", *sp))?;
                Ok(EV::Num(match op.as_str() {
                    "-" => -x,
                    "!" => {
                        if x == 0.0 {
                            1.0
                        } else {
                            0.0
                        }
                    }
                    _ => x,
                }))
            }
            Expr::Bin(op, a, b, sp) => {
                let x = self.eval(a, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if op == "&&" {
                    if x == 0.0 {
                        return Ok(EV::Num(0.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                if op == "||" {
                    if x != 0.0 {
                        return Ok(EV::Num(1.0));
                    }
                    let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                    return Ok(EV::Num(if y != 0.0 { 1.0 } else { 0.0 }));
                }
                let y = self.eval(b, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                let b2 = |c: bool| if c { 1.0 } else { 0.0 };
                Ok(EV::Num(match op.as_str() {
                    "+" => x + y,
                    "-" => x - y,
                    "*" => x * y,
                    "/" => x / y,
                    "^" => x.powf(y),
                    "<" => b2(x < y),
                    ">" => b2(x > y),
                    "<=" => b2(x <= y),
                    ">=" => b2(x >= y),
                    "==" => b2(x == y),
                    "!=" => b2(x != y),
                    _ => return Err(err("unknown operator", *sp)),
                }))
            }
            Expr::Ternary(c, a, b, sp) => {
                let cv = self.eval(c, locals)?.num().ok_or_else(|| err("expected a number", *sp))?;
                if cv != 0.0 {
                    self.eval(a, locals)
                } else {
                    self.eval(b, locals)
                }
            }
            Expr::Tuple(items, _) => {
                let mut out = Vec::new();
                for it in items {
                    out.push(self.eval(it, locals)?);
                }
                Ok(EV::Tuple(out))
            }
            Expr::Block(binds, body, _) => {
                let mut l2 = locals.clone();
                for (n, ex) in binds {
                    let v = self.eval(ex, &l2)?;
                    l2.insert(n.clone(), v);
                }
                self.eval(body, &l2)
            }
        }
    }

    fn call(&self, name: &str, args: &[Expr], locals: &HashMap<String, EV>, sp: Span) -> Result<EV, Diag> {
        if let Some(f) = self.funcs.get(name) {
            let mut l2 = locals.clone();
            for (i, p) in f.params.iter().enumerate() {
                let v = match args.get(i) {
                    Some(a) => self.eval(a, locals)?,
                    None => EV::Num(0.0),
                };
                l2.insert(p.clone(), v);
            }
            return self.eval_term(&f.body, &l2);
        }
        let mut xs = Vec::new();
        for a in args {
            match self.eval(a, locals)? {
                EV::Num(v) => xs.push(v),
                _ => return Err(err("expected a number", a.span())),
            }
        }
        let a = |i: usize| xs.get(i).copied().unwrap_or(0.0);
        let v = match name {
            "sin" => a(0).sin(),
            "cos" => a(0).cos(),
            "tan" => a(0).tan(),
            "sqrt" => a(0).sqrt(),
            "abs" => a(0).abs(),
            "exp" => a(0).exp(),
            "ln" => a(0).ln(),
            "log" => a(0).log10(),
            "floor" => a(0).floor(),
            "round" => a(0).round(),
            "pow" => a(0).powf(a(1)),
            "min" => xs.iter().cloned().fold(f64::INFINITY, f64::min),
            "max" => xs.iter().cloned().fold(f64::NEG_INFINITY, f64::max),
            "clamp" => a(0).max(a(1)).min(a(2)),
            _ => return Err(err(&format!("unknown function '{}'", name), sp)),
        };
        Ok(EV::Num(v))
    }
}
// Syntax tree for a Lini document.

use crate::diag::Span;

#[derive(Debug, Clone)]
pub struct Doc {
    pub sheet: Option<Sheet>,
    pub stmts: Vec<Stmt>,
}

#[derive(Debug, Clone)]
pub struct Sheet {
    pub items: Vec<SheetItem>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum SheetItem {
    Decl(Decl),
    Var(Decl),
    Binding(Binding),
    Rule(Rule),
    Define(Define),
}

#[derive(Debug, Clone)]
pub struct Decl {
    pub name: String,
    pub name_span: Span,
    pub value: Value,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Binding {
    pub name: String,
    pub params: Option<Vec<String>>,
    pub expr: Term,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Rule {
    pub selector: Vec<Compound>,
    pub decls: Vec<Decl>,
    pub span: Span,
}

#[derive(Debug, Clone, Default)]
pub struct Compound {
    pub bars: bool,
    pub type_name: Option<String>, // '-' for the link selector |-|
    pub id: Option<String>,
    pub classes: Vec<String>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub struct Define {
    pub name: String,
    pub base: String,
    pub decls: Vec<Decl>,
    pub body: Option<Vec<Stmt>>,
    pub span: Span,
    pub head_span: Span,
}

#[derive(Debug, Clone)]
pub struct Value {
    // comma-separated groups, each a space-separated run of terms
    pub groups: Vec<Vec<Term>>,
    pub span: Span,
}

#[derive(Debug, Clone)]
pub enum Term {
    Num(f64, String, Span),
    Percent(f64, String, Span),
    Ident(String, Span),
    Str(String, Span),
    Hash(String, Span),
    Var(String, Span),
    Call(String, Vec<Expr>, Span),
    Group(Expr, Span),
    Tagged(Box<Term>, String, Span), // term ':' tag (draw segment names)
}

impl Term {
    pub fn span(&self) -> Span {
        match self {
            Term::Num(_, _, s)
            | Term::Percent(_, _, s)
            | Term::Ident(_, s)
            | Term::Str(_, s)
            | Term::Hash(_, s)
            | Term::Var(_, s)
            | Term::Call(_, _, s)
            | Term::Group(_, s)
            | Term::Tagged(_, _, s) => *s,
        }
    }
}

#[derive(Debug, Clone)]
pub enum Expr {
    Num(f64, Span),
    Percent(f64, Span),
    Ident(String, Span),
    Str(String, Span),
    Var(String, Span),
    Hash(String, Span),
    Call(String, Vec<Expr>, Span),
    Unary(String, Box<Expr>, Span),
    Bin(String, Box<Expr>, Box<Expr>, Span),
    Ternary(Box<Expr>, Box<Expr>, Box<Expr>, Span),
    Tuple(Vec<Expr>, Span),
    Block(Vec<(String, Expr)>, Box<Expr>, Span), // (a = 1; b = 2; expr)
}

impl Expr {
    pub fn span(&self) -> Span {
        match self {
            Expr::Num(_, s)
            | Expr::Percent(_, s)
            | Expr::Ident(_, s)
            | Expr::Str(_, s)
            | Expr::Var(_, s)
            | Expr::Hash(_, s)
            | Expr::Call(_, _, s)
            | Expr::Unary(_, _, s)
            | Expr::Bin(_, _, _, s)
            | Expr::Ternary(_, _, _, s)
            | Expr::Tuple(_, s)
            | Expr::Block(_, _, s) => *s,
        }
    }
}

