use std::collections::HashMap;
use std::sync::OnceLock;

pub static SANS_400: &[u8] = include_bytes!("../fonts/sans-400.ttf");
pub static SANS_500: &[u8] = include_bytes!("../fonts/sans-500.ttf");
pub static SANS_600: &[u8] = include_bytes!("../fonts/sans-600.ttf");
pub static SANS_700: &[u8] = include_bytes!("../fonts/sans-700.ttf");
pub static CODE_400: &[u8] = include_bytes!("../fonts/code-400.ttf");
pub static CODE_500: &[u8] = include_bytes!("../fonts/code-500.ttf");
pub static CODE_600: &[u8] = include_bytes!("../fonts/code-600.ttf");
pub static CODE_700: &[u8] = include_bytes!("../fonts/code-700.ttf");

pub struct Font {
    pub data: &'static [u8],
    pub upem: f64,
    pub cmap: HashMap<u32, u16>,
    pub adv: Vec<u16>,
    pub loca: Vec<u32>,
    pub glyf_off: usize,
    pub ascent: i16,
    pub descent: i16,
}

fn rd16(d: &[u8], o: usize) -> u16 {
    u16::from_be_bytes([d[o], d[o + 1]])
}
fn rd32(d: &[u8], o: usize) -> u32 {
    u32::from_be_bytes([d[o], d[o + 1], d[o + 2], d[o + 3]])
}

impl Font {
    fn parse(data: &'static [u8]) -> Font {
        let n = rd16(data, 4) as usize;
        let mut tables: HashMap<String, (usize, usize)> = HashMap::new();
        for i in 0..n {
            let o = 12 + 16 * i;
            let tag = String::from_utf8_lossy(&data[o..o + 4]).to_string();
            tables.insert(tag, (rd32(data, o + 8) as usize, rd32(data, o + 12) as usize));
        }
        let head = tables["head"].0;
        let upem = rd16(data, head + 18) as f64;
        let index_to_loc = rd16(data, head + 50) as i16;
        let hhea = tables["hhea"].0;
        let ascent = rd16(data, hhea + 4) as i16;
        let descent = rd16(data, hhea + 6) as i16;
        let nhm = rd16(data, hhea + 34) as usize;
        let maxp = tables["maxp"].0;
        let ng = rd16(data, maxp + 4) as usize;
        let hmtx = tables["hmtx"].0;
        let mut adv = Vec::with_capacity(ng);
        for i in 0..ng {
            if i < nhm {
                adv.push(rd16(data, hmtx + 4 * i));
            } else {
                let last = *adv.last().unwrap_or(&0);
                adv.push(last);
            }
        }
        let mut cmap = HashMap::new();
        let cm = tables["cmap"].0;
        let nt = rd16(data, cm + 2) as usize;
        for i in 0..nt {
            let so = cm + rd32(data, cm + 4 + 8 * i + 4) as usize;
            let fmt = rd16(data, so);
            if fmt == 12 {
                let ngr = rd32(data, so + 12) as usize;
                for j in 0..ngr {
                    let a = rd32(data, so + 16 + 12 * j);
                    let b = rd32(data, so + 20 + 12 * j);
                    let g = rd32(data, so + 24 + 12 * j);
                    for c in a..=b {
                        cmap.insert(c, (g + (c - a)) as u16);
                    }
                }
            } else if fmt == 4 {
                let segx2 = rd16(data, so + 6) as usize;
                let seg = segx2 / 2;
                for k in 0..seg {
                    let end = rd16(data, so + 14 + 2 * k) as u32;
                    let start = rd16(data, so + 16 + segx2 + 2 * k) as u32;
                    let delta = rd16(data, so + 16 + 2 * segx2 + 2 * k) as i16 as i32;
                    let roff_pos = so + 16 + 3 * segx2 + 2 * k;
                    let roff = rd16(data, roff_pos) as usize;
                    for c in start..=end {
                        if c == 0xffff {
                            continue;
                        }
                        let g = if roff == 0 {
                            ((c as i32 + delta) & 0xffff) as u16
                        } else {
                            let p = roff_pos + roff + 2 * (c - start) as usize;
                            let g = rd16(data, p);
                            if g != 0 {
                                ((g as i32 + delta) & 0xffff) as u16
                            } else {
                                0
                            }
                        };
                        cmap.entry(c).or_insert(g);
                    }
                }
            }
        }
        let mut loca = Vec::with_capacity(ng + 1);
        if let Some(&(lo, _)) = tables.get("loca") {
            for i in 0..=ng {
                if index_to_loc == 0 {
                    loca.push(rd16(data, lo + 2 * i) as u32 * 2);
                } else {
                    loca.push(rd32(data, lo + 4 * i));
                }
            }
        }
        let glyf_off = tables.get("glyf").map(|x| x.0).unwrap_or(0);
        Font { data, upem, cmap, adv, loca, glyf_off, ascent, descent }
    }

    pub fn glyph_for(&self, c: char) -> Option<u16> {
        self.cmap.get(&(c as u32)).copied()
    }

    // Glyph outline as quadratic contours: list of contours, each a list of (x, y, on_curve).
    pub fn outline(&self, gid: u16) -> Vec<Vec<(f64, f64, bool)>> {
        let mut out = Vec::new();
        self.outline_into(gid, 0.0, 0.0, &mut out, 0);
// Diagnostics: errors and warnings with stable codes and source spans.

#[derive(Debug, Clone, Copy, PartialEq, Default)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    pub fn new(start: usize, end: usize) -> Span {
        Span { start, end }
    }
    pub fn to(self, other: Span) -> Span {
        Span { start: self.start.min(other.start), end: self.end.max(other.end) }
    }
}

#[derive(Debug, Clone, PartialEq)]
pub enum Severity {
    Error,
    Warning,
}

#[derive(Debug, Clone)]
pub struct Diag {
    pub family: String,
    pub severity: Severity,
    pub message: String,
    pub span: Span,
    pub fixes: Vec<Fix>,
}

#[derive(Debug, Clone)]
pub struct Fix {
    pub message: String,
    pub span: Span,
    pub replacement: String,
}

impl Diag {
    pub fn error(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Error, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn warning(family: &str, message: &str, span: Span) -> Diag {
        Diag { family: family.to_string(), severity: Severity::Warning, message: message.to_string(), span, fixes: vec![] }
    }
    pub fn code(&self) -> &'static str {
        family_code(&self.family)
    }
}

pub fn family_code(family: &str) -> &'static str {
    match family {
        "lex" => "L000",
        "unterminated-string" => "L001",
        "bad-escape" => "L002",
        "unexpected-char" => "L004",
        "parse" => "P000",
        "expected-token" => "P001",
        "empty-bars" => "P002",
        "invalid-id" => "P003",
        "declaration-outside-block" => "P004",
        "stylesheet-after-canvas" => "P005",
        "text-carries-children" => "P006",
        "spaced-call-paren" => "P007",
        "validate" => "V000",
        "unknown-property" => "V001",
        "class-never-worn" => "V004",
        "malformed-value" => "V005",
        "invalid-color" => "V010",
        "resolve" => "R000",
        "unknown-type" => "R001",
        "unknown-class" => "R002",
        "duplicate-id" => "R003",
        "unknown-endpoint" => "R008",
        "chain-too-short" => "R009",
        "asset-not-found" => "R010",
        "layout" => "Y000",
        "missing-required-property" => "Y001",
        "chart-type" => "Y009",
        _ => "X000",
    }
}

// Line/column (1-based, columns counted in chars) of a byte offset.
pub fn line_col(src: &str, off: usize) -> (usize, usize) {
    let mut line = 1;
    let mut col = 1;
    for (i, c) in src.char_indices() {
        if i >= off {
            break;
        }
        if c == '\n' {
            line += 1;
            col = 1;
        } else {
            col += 1;
        }
    }
    (line, col)
}

pub fn render_text(file: &str, src: &str, d: &Diag) -> String {
    let (l, c) = line_col(src, d.span.start);
    let sev = match d.severity {
        Severity::Error => "error",
        Severity::Warning => "warning",
    };
    format!("{}:{}:{}: {}: {}", file, l, c, sev, d.message)
}

pub fn json_escape(s: &str) -> String {
    let mut o = String::new();
    for c in s.chars() {
        match c {
            '"' => o.push_str("\\\""),
            '\\' => o.push_str("\\\\"),
            '\n' => o.push_str("\\n"),
            '\r' => o.push_str("\\r"),
            '\t' => o.push_str("\\t"),
            c if (c as u32) < 0x20 => o.push_str(&format!("\\u{:04x}", c as u32)),
            c => o.push(c),
        }
    }
    o
}

pub fn render_json(file: &str, src: &str, diags: &[Diag]) -> String {
    let mut o = String::new();
    o.push_str("{\n");
    o.push_str(&format!("  \"file\": \"{}\",\n", json_escape(file)));
    if diags.is_empty() {
        o.push_str("  \"diagnostics\": []\n}\n");
        return o;
    }
    o.push_str("  \"diagnostics\": [\n");
    for (i, d) in diags.iter().enumerate() {
        let (l, c) = line_col(src, d.span.start);
        let (el, ec) = line_col(src, d.span.end);
        let sev = match d.severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
        };
        o.push_str("    {\n");
        o.push_str(&format!("      \"code\": \"{}\",\n", d.code()));
        o.push_str(&format!("      \"family\": \"{}\",\n", json_escape(&d.family)));
        o.push_str(&format!("      \"severity\": \"{}\",\n", sev));
        o.push_str(&format!("      \"message\": \"{}\",\n", json_escape(&d.message)));
        o.push_str("      \"span\": {\n");
        o.push_str(&format!("        \"start\": {},\n", d.span.start));
        o.push_str(&format!("        \"end\": {},\n", d.span.end));
        o.push_str(&format!("        \"line\": {},\n", l));
        o.push_str(&format!("        \"col\": {},\n", c));
        o.push_str(&format!("        \"endLine\": {},\n", el));
        o.push_str(&format!("        \"endCol\": {}\n", ec));
        if d.fixes.is_empty() {
            o.push_str("      }\n");
        } else {
            o.push_str("      },\n");
            o.push_str("      \"fixes\": [\n");
            for (k, f) in d.fixes.iter().enumerate() {
                o.push_str("        {\n");
                o.push_str(&format!("          \"message\": \"{}\",\n", json_escape(&f.message)));
                o.push_str(&format!("          \"start\": {},\n", f.span.start));
                o.push_str(&format!("          \"end\": {},\n", f.span.end));
                o.push_str(&format!("          \"replacement\": \"{}\"\n", json_escape(&f.replacement)));
                o.push_str(if k + 1 < d.fixes.len() { "        },\n" } else { "        }\n" });
            }
            o.push_str("      ]\n");
        }
        o.push_str(if i + 1 < diags.len() { "    },\n" } else { "    }\n" });
    }
    o.push_str("  ]\n}\n");
    o
}

