#!/usr/bin/env python3
# qq.py [-g regex] [-b BIN] snippet...   (or -f file with snippets separated by lines '---')
# Runs the original (or BIN) on each snippet; prints exit/stderr and the scene body (or grep matches).
import subprocess, sys, os, re, tempfile
args = sys.argv[1:]
pat = None
binp = '/workspace/executable'
snips = []
extra = []
full = False
while args:
    a = args.pop(0)
    if a == '-g':
        pat = re.compile(args.pop(0))
    elif a == '-b':
        binp = args.pop(0)
    elif a == '-a':
        extra = args.pop(0).split()
    elif a == '-F':
        full = True
    elif a == '-f':
        txt = open(args.pop(0)).read()
        snips += [s.strip('\n') for s in txt.split('\n---\n')]
    else:
        snips.append(a)
for s in snips:
    d = tempfile.mkdtemp(dir='/tmp/chart')
    p = os.path.join(d, 'r_in.lini')
    open(p, 'w').write(s)
    r = subprocess.run([binp] + extra + ['r_in.lini'], capture_output=True, cwd=d)
    out = r.stdout.decode()
    print('=== ' + s.replace('\n', ' ')[:200])
    print('[exit %d] %s' % (r.returncode, r.stderr.decode().strip()))
    lines = out.split('\n')
    if pat:
        for l in lines:
            if pat.search(l):
                print(l)
    elif full:
        print(out)
    else:
        on = False
        for l in lines:
            if '<g class="lini-scene">' in l:
                on = True
            if on:
                print(l)
    os.remove(p)
    os.rmdir(d)

