// Chart model: the chart node, its axes and series, read from the cascaded
// properties of the node tree.

use crate::ast::{Decl, Term, Value};
use crate::compile::Ctx;
use crate::diag::{Diag, Span};
use crate::types::Prim;

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Kind {
    Bars,
    Line,
    Area,
    Dots,
    Bubble,
}

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum Dir {
    Column,
    Row,
    Radial,
}

#[derive(Clone, Debug, PartialEq)]
pub enum Fmt {
    Decimal(usize),
    Percent(usize),
    Other(String),
}

#[derive(Clone, Debug)]
pub enum StepSpec {
    Num(f64),
    Cal(String),
}

#[derive(Clone, Debug)]
pub struct Axis {
    pub node: usize,
    pub id: Option<String>,
    pub title: Option<String>,
    pub side: Option<String>,
    pub range: Option<(f64, f64)>,
    pub range_time: bool,
    pub step: Option<StepSpec>,
    pub ticks: Option<Vec<f64>>,
    pub ticks_none: bool,
    pub gridlines: bool,
    pub unit: String,
    pub format: Option<Fmt>,
    pub log: bool,
}

#[derive(Clone, Debug)]
pub struct Series {
    pub node: usize,
    pub kind: Kind,
    pub name: Option<String>,
    pub index: usize,
    // category data (one value per category)
    pub vals: Vec<f64>,
    // point data
    pub pts: Vec<(f64, f64)>,
    pub points: bool,
    pub time_x: bool,
    pub fns: Vec<Term>,
    pub labels: Vec<String>,
    pub fill: Option<Value>,
    pub stroke: Option<Value>,
    pub stroke_width: Option<f64>,
    pub stroke_style: Option<String>,
    pub axis: Option<String>,
    pub curve: String,
    pub marker: Option<String>,
    pub baseline: Option<f64>,
    pub at: Option<(f64, f64)>,
    pub value: Option<f64>,
    pub tooltip: Option<String>,
    pub span: Span,
}

#[derive(Clone, Debug)]
pub struct Band {
    pub node: usize,
    pub name: Option<String>,
    pub range: (f64, f64),
    pub axis: Option<String>,
    pub fill: Option<Value>,
    pub time: bool,
}

#[derive(Clone, Debug)]
pub struct Mark {
    pub node: usize,
    pub name: Option<String>,
    pub at: f64,
    pub axis: Option<String>,
    pub stroke: Option<Value>,
    pub color: Option<Value>,
    pub stroke_style: Option<String>,
    pub stroke_width: Option<f64>,
    pub time: bool,
}

#[derive(Clone, Debug)]
pub struct Slice {
    pub node: usize,
    pub name: Option<String>,
    pub value: f64,
    pub fill: Option<Value>,
    pub stroke: Option<Value>,
}

#[derive(Clone, Debug)]
pub struct Chart {
    pub node: usize,
    pub pie: bool,
    pub dir: Dir,
    pub categories: Option<Vec<String>>,
    pub bars_mode: String,
    pub tooltip: String,
    pub format: Option<Fmt>,
    pub clearance: f64,
    pub gap: f64,
    pub samples: usize,
    pub hole: f64,
    pub title: Option<String>,
    pub axes: Vec<Axis>,
    pub series: Vec<Series>,
    pub bands: Vec<Band>,
    pub marks: Vec<Mark>,
    pub slices: Vec<Slice>,
}

// The user-written declarations of a node: type rules, classes, id rules and
// inline style, without the built-in type defaults.
pub fn user_props(ctx: &Ctx, n: usize) -> Vec<(String, Value)> {
    let sheet = &ctx.sheet;
    let node = &ctx.nodes[n];
    let mut props: Vec<(String, Value)> = Vec::new();
    fn set(props: &mut Vec<(String, Value)>, d: &Decl) {
        if let Some(e) = props.iter_mut().find(|e| e.0 == d.name) {
            e.1 = d.value.clone();
        } else {
            props.push((d.name.clone(), d.value.clone()));
        }
    }
    for t in node.chain.iter().rev() {
        if let Some(df) = sheet.define(t) {
            for d in &df.decls {
                set(&mut props, d);
            }
        }
        for d in sheet.type_rule(t) {
            set(&mut props, d);
        }
    }
    for c in &node.classes {
        if let Some(cr) = sheet.class(c) {
            for d in &cr.decls {
                set(&mut props, d);
            }
        }
    }
    if let Some(id) = &node.id {
        for (rid, ds) in &sheet.id_rules {
            if rid == id {
                for d in ds {
                    set(&mut props, d);
                }
            }
        }
    }
    for d in &node.inline {
        set(&mut props, d);
    }
    props
}

pub fn get<'a>(p: &'a [(String, Value)], k: &str) -> Option<&'a Value> {
    p.iter().find(|e| e.0 == k).map(|e| &e.1)
}

pub fn ident(v: &Value) -> Option<String> {
    match crate::style::single_term(v) {
        Some(Term::Ident(s, _)) => Some(s.clone()),
        Some(Term::Str(s, _)) => Some(s.clone()),
        _ => None,
    }
}

pub fn num(ctx: &Ctx, v: &Value) -> Option<f64> {
    crate::style::value_num(&ctx.sheet.env, v)
}

pub fn term_num(ctx: &Ctx, t: &Term) -> Option<f64> {
    crate::style::term_num(&ctx.sheet.env, t)
}

// "YYYY-MM-DD" (optionally "THH:MM") → days since 1970-01-01.
pub fn parse_date(s: &str) -> Option<f64> {
    let b = s.as_bytes();
    if b.len() < 10 || b[4] != b'-' || b[7] != b'-' {
        return None;
    }
    let y: i64 = s[0..4].parse().ok()?;
    let m: i64 = s[5..7].parse().ok()?;
    let d: i64 = s[8..10].parse().ok()?;
    if !(1..=12).contains(&m) || !(1..=31).contains(&d) {
        return None;
    }
    let mut frac = 0.0;
    if b.len() > 10 {
        if b.len() >= 16 && (b[10] == b'T' || b[10] == b' ') && b[13] == b':' {
            let hh: f64 = s[11..13].parse().ok()?;
            let mm: f64 = s[14..16].parse().ok()?;
            frac = (hh * 60.0 + mm) / 1440.0;
        } else {
            return None;
        }
    }
    Some(days_from_civil(y, m, d) as f64 + frac)
}

pub fn days_from_civil(y: i64, m: i64, d: i64) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = if y >= 0 { y } else { y - 399 } / 400;
    let yoe = y - era * 400;
    let mp = (m + 9) % 12;
    let doy = (153 * mp + 2) / 5 + d - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

pub fn civil_from_days(z: i64) -> (i64, i64, i64) {
    let z = z + 719468;
    let era = if z >= 0 { z } else { z - 146096 } / 146097;
    let doe = z - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    (if m <= 2 { y + 1 } else { y }, m, d)
}

// A number or a date literal.
fn term_val(ctx: &Ctx, t: &Term) -> Option<(f64, bool)> {
    match t {
        Term::Str(s, _) => parse_date(s).map(|d| (d, true)),
        _ => term_num(ctx, t).map(|x| (x, false)),
    }
}

fn parse_fmt(v: &Value) -> Option<Fmt> {
    let g = v.groups.first()?;
    let name = match g.first()? {
        Term::Ident(s, _) => s.clone(),
        _ => return None,
    };
    let n = match g.get(1) {
        Some(Term::Num(x, _, _)) => Some(*x as usize),
        _ => None,
    };
    Some(match name.as_str() {
        "decimal" => Fmt::Decimal(n.unwrap_or(0)),
        "percent" => Fmt::Percent(n.unwrap_or(0)),
        _ => Fmt::Other(name),
    })
}

fn texts_of(ctx: &Ctx, n: usize) -> Option<String> {
    for &c in &ctx.nodes[n].children {
        if ctx.nodes[c].prim == Prim::Text {
            return ctx.nodes[c].text.clone();
        }
    }
    None
}

fn strings(v: &Value) -> Vec<String> {
    let mut out = Vec::new();
    for g in &v.groups {
        let mut parts = Vec::new();
        for t in g {
            match t {
                Term::Str(s, _) | Term::Ident(s, _) => parts.push(s.clone()),
                Term::Num(_, raw, _) => parts.push(raw.clone()),
                _ => {}
            }
        }
        out.push(parts.join(" "));
    }
    out
}

fn layout_err(msg: &str, span: Span) -> Diag {
    Diag::error("layout", msg, span)
}

fn data_err(msg: &str, span: Span) -> Diag {
    Diag::error("chart-data", msg, span)
}

pub const SERIES_TYPES: &[&str] = &["bars", "area", "dots", "bubble", "line"];

pub fn build(ctx: &Ctx, i: usize) -> Result<Chart, Diag> {
    let pie = ctx.comp[i].layout == "pie";
    let node = &ctx.nodes[i];
    let props: Vec<(String, Value)> = node.props.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
    let p = |k: &str| get(&props, k);
    let nospan = Span::default();
    let dir = match p("direction").and_then(ident).as_deref() {
        None | Some("column") => Dir::Column,
        Some("row") => Dir::Row,
        Some("radial") => Dir::Radial,
        Some(_) => return Err(layout_err("'direction' is column, row, or radial", nospan)),
    };
    let bars_mode = match p("bars").and_then(ident) {
        None => "grouped".to_string(),
        Some(s) if s == "grouped" || s == "stacked" || s == "overlay" => s,
        Some(_) => return Err(layout_err("'bars' is grouped, stacked, or overlay", nospan)),
    };
    let tooltip = match p("tooltip").and_then(ident) {
        None => "auto".to_string(),
        Some(s) if s == "none" || s == "hover" || s == "auto" || s == "always" => s,
        Some(_) => return Err(layout_err("'tooltip' is none, hover, auto, or always", nospan)),
    };
    let categories = p("categories").map(strings);
    let format = p("format").and_then(parse_fmt);
    let clearance = p("clearance").and_then(|v| num(ctx, v)).unwrap_or(6.0);
    let gap = ctx.comp[i].gap.0;
    let samples = p("samples").and_then(|v| num(ctx, v)).map(|x| x.max(2.0) as usize).unwrap_or(24);
    let hole = match p("hole").and_then(|v| num(ctx, v)) {
        Some(h) => {
            if !(0.0..1.0).contains(&h) {
                return Err(layout_err("'hole' is a fraction 0..1", nospan));
            }
            h
        }
        None => 0.0,
    };
    let mut ch = Chart {
        node: i,
        pie,
        dir,
        categories,
        bars_mode,
        tooltip,
        format,
        clearance,
        gap,
        samples,
        hole,
        title: None,
        axes: vec![],
        series: vec![],
        bands: vec![],
        marks: vec![],
        slices: vec![],
    };
    let mut sidx = 0;
    let children = node.children.clone();
    for &c in &children {
        let cn = &ctx.nodes[c];
        if cn.prim == Prim::Text {
            if ch.title.is_none() {
                ch.title = cn.text.clone();
            }
            continue;
        }
        let up = user_props(ctx, c);
        let u = |k: &str| get(&up, k).or_else(|| ctx.nodes[c].props.get(k));
        let name = texts_of(ctx, c);
        if pie {
            if !cn.is("slice") {
                return Err(layout_err("a pie's children are '|slice|' only", cn.span));
            }
            let value = match u("value").and_then(|v| num(ctx, v)) {
                Some(v) => v,
                None => return Err(layout_err("a '|slice|' needs a 'value:'", cn.span)),
            };
            if value < 0.0 {
                return Err(layout_err("a '|slice|' value must be ≥ 0", cn.span));
            }
            ch.slices.push(Slice { node: c, name, value, fill: get(&up, "fill").cloned(), stroke: get(&up, "stroke").cloned() });
            continue;
        }
        if cn.is("slice") {
            return Err(Diag::error("chart-type", "'|slice|' belongs in a 'layout: pie'", cn.span));
        }
        if cn.is("axis") {
            let side = u("side").and_then(ident);
            if let Some(s) = &side {
                if !matches!(s.as_str(), "bottom" | "top" | "left" | "right") {
                    return Err(layout_err("'side' is bottom, top, left, or right", cn.span));
                }
            }
            let mut range = None;
            let mut range_time = false;
            if let Some(v) = u("range") {
                let ts: Vec<&Term> = v.groups.iter().flatten().collect();
                if ts.len() >= 2 {
                    if let (Some(a), Some(b)) = (term_val(ctx, ts[0]), term_val(ctx, ts[1])) {
                        if a.0 == b.0 {
                            return Err(layout_err("'range' needs distinct ends", nospan));
                        }
                        range = Some((a.0, b.0));
                        range_time = a.1 || b.1;
                    }
                }
            }
            let step = u("step").and_then(|v| match crate::style::single_term(v) {
                Some(Term::Ident(s, _)) => Some(StepSpec::Cal(s.clone())),
                Some(t) => term_num(ctx, t).map(StepSpec::Num),
                None => None,
            });
            let mut ticks_none = false;
            let ticks = u("ticks").and_then(|v| {
                if ident(v).as_deref() == Some("none") {
                    ticks_none = true;
                    return None;
                }
                let mut xs = Vec::new();
                for t in v.groups.iter().flatten() {
                    if let Some((x, _)) = term_val(ctx, t) {
                        xs.push(x);
                    }
                }
                Some(xs)
            });
            let gridlines = u("gridlines").and_then(ident).as_deref() != Some("none");
            let unit = u("unit").and_then(ident).unwrap_or_default();
            let format = u("format").and_then(parse_fmt);
            let log = u("scale").and_then(ident).as_deref() == Some("log");
            ch.axes.push(Axis {
                node: c,
                id: cn.id.clone(),
                title: name,
                side,
                range,
                range_time,
                step,
                ticks,
                ticks_none,
                gridlines,
                unit,
                format,
                log,
            });
            continue;
        }
        if cn.is("band") {
            let mut range = (0.0, 0.0);
            let mut time = false;
            if let Some(v) = u("range") {
                let ts: Vec<&Term> = v.groups.iter().flatten().collect();
                if ts.len() >= 2 {
                    if let (Some(a), Some(b)) = (term_val(ctx, ts[0]), term_val(ctx, ts[1])) {
                        range = (a.0, b.0);
                        time = a.1 || b.1;
                    }
                }
            }
            ch.bands.push(Band { node: c, name, range, axis: u("axis").and_then(ident), fill: get(&up, "fill").cloned(), time });
            continue;
        }
        if cn.is("mark") {
            let (at, time) = match u("at") {
                Some(v) => match crate::style::single_term(v).and_then(|t| term_val(ctx, t)) {
                    Some(x) => x,
                    None => (0.0, false),
                },
                None => (0.0, false),
            };
            let axis = u("axis").and_then(ident);
            if axis.is_none() {
                return Err(layout_err("a '|mark|' needs 'axis:' to place it", cn.span));
            }
            ch.marks.push(Mark {
                node: c,
                name,
                at,
                axis,
                stroke: get(&up, "stroke").cloned(),
                color: get(&up, "color").cloned(),
                stroke_style: get(&up, "stroke-style").and_then(ident),
                stroke_width: get(&up, "stroke-width").and_then(|v| num(ctx, v)),
                time,
            });
            continue;
        }
        let kind = if cn.is("bars") {
            Kind::Bars
        } else if cn.is("area") {
            Kind::Area
        } else if cn.is("dots") {
            Kind::Dots
        } else if cn.is("bubble") {
            Kind::Bubble
        } else if cn.is("line") {
            Kind::Line
        } else {
            return Err(layout_err("a chart's children are series (e.g. '|bars|', '|line|') and '|axis|'", cn.span));
        };
        let mut s = Series {
            node: c,
            kind,
            name,
            index: sidx,
            vals: vec![],
            pts: vec![],
            points: false,
            time_x: false,
            fns: vec![],
            labels: vec![],
            fill: get(&up, "fill").cloned(),
            stroke: get(&up, "stroke").cloned(),
            stroke_width: get(&up, "stroke-width").and_then(|v| num(ctx, v)),
            stroke_style: get(&up, "stroke-style").and_then(ident),
            axis: u("axis").and_then(ident),
            curve: "linear".into(),
            marker: None,
            baseline: u("baseline").and_then(|v| num(ctx, v)),
            at: None,
            value: u("value").and_then(|v| num(ctx, v)),
            tooltip: u("tooltip").and_then(ident),
            span: cn.span,
        };
        sidx += 1;
        if let Some(v) = u("curve").and_then(ident) {
            if !matches!(v.as_str(), "linear" | "smooth" | "step") {
                return Err(layout_err("'curve' is linear, smooth, or step", nospan));
            }
            s.curve = v;
        }
        if let Some(v) = get(&up, "marker").and_then(ident) {
            if !matches!(v.as_str(), "dot" | "circle" | "none") {
                return Err(Diag::error("resolve", &format!("invalid marker value '{}'", v), cn.span));
            }
            if v != "none" {
                s.marker = Some(v);
            }
        }
        if kind == Kind::Bubble {
            if let Some(v) = u("at") {
                let ts: Vec<&Term> = v.groups.iter().flatten().collect();
                if ts.len() >= 2 {
                    if let (Some(a), Some(b)) = (term_val(ctx, ts[0]), term_val(ctx, ts[1])) {
                        s.at = Some((a.0, b.0));
                        s.time_x = a.1;
                    }
                }
            }
        } else {
            let data = u("data");
            let fnv = u("fn");
            if data.is_some() && fnv.is_some() {
                return Err(data_err("a series takes 'data' or 'fn', not both", cn.span));
            }
            if let Some(v) = fnv {
                for g in &v.groups {
                    if let Some(t) = g.first() {
                        s.fns.push(t.clone());
                    }
                }
            } else if let Some(v) = data {
                let pairs = v.groups.iter().any(|g| g.len() >= 2);
                if pairs || v.groups.iter().any(|g| matches!(g.first(), Some(Term::Str(..)))) {
                    for g in &v.groups {
                        if g.len() != 2 {
                            return Err(data_err("point data is 'x y' pairs", cn.span));
                        }
                        let a = term_val(ctx, &g[0]);
                        let b = term_val(ctx, &g[1]);
                        match (a, b) {
                            (Some(a), Some(b)) => {
                                s.time_x = s.time_x || a.1;
                                s.pts.push((a.0, b.0));
                            }
                            _ => return Err(data_err("point data is 'x y' pairs", cn.span)),
                        }
                    }
                    s.points = true;
                } else {
                    for g in &v.groups {
                        match g.first().and_then(|t| term_num(ctx, t)) {
                            Some(x) => s.vals.push(x),
                            None => return Err(data_err("point data is 'x y' pairs", cn.span)),
                        }
                    }
                }
            } else {
                return Err(data_err("a series needs 'data' or 'fn'", cn.span));
            }
        }
        if let Some(v) = u("labels") {
            s.labels = strings(v);
        }
        ch.series.push(s);
    }
    if pie {
        if ch.slices.is_empty() {
            return Err(layout_err("a pie needs at least one '|slice|'", ctx.nodes[i].span));
        }
    } else if ch.series.is_empty() {
        return Err(layout_err("a chart needs at least one series", ctx.nodes[i].span));
    }
    // category / data consistency
    if !pie {
        for s in &ch.series {
            if s.kind == Kind::Bubble {
                continue;
            }
            if let Some(cats) = &ch.categories {
                if s.points || !s.fns.is_empty() {
                    return Err(layout_err("point / formula data needs a numeric x axis, not 'categories'", s.span));
                }
                if s.vals.len() != cats.len() {
                    return Err(layout_err(
                        &format!("series data has {} values but the chart has {} categories", s.vals.len(), cats.len()),
                        s.span,
                    ));
                }
            }
            let n = if s.points { s.pts.len() } else { s.vals.len() };
            if !s.labels.is_empty() && s.fns.is_empty() && s.labels.len() != n {
                return Err(data_err(
                    &format!("'labels' has {} entries but the series has {} data points", s.labels.len(), n),
                    s.span,
                ));
            }
        }
        for s in &ch.series {
            if let Some(a) = &s.axis {
                if !ch.axes.iter().any(|x| x.id.as_deref() == Some(a.as_str())) {
                    return Err(layout_err(&format!("axis '{}' not found", a), s.span));
                }
            }
        }
    }
    Ok(ch)
}

// Scales: nice tick steps, domains, and number / date formatting.

use super::model::{civil_from_days, Fmt};
use crate::util::f4;

// Smallest step from the 1-2-5 ladder that cuts `span` into at most five parts.
pub fn nice_step(span: f64) -> f64 {
    if !(span > 0.0) || !span.is_finite() {
        return 1.0;
    }
    let mut p = 10f64.powf((span / 5.0).log10().floor() - 1.0);
    for _ in 0..40 {
        for m in [1.0, 2.0, 5.0] {
            let s = m * p;
            if span / s <= 5.0 + 1e-9 {
                return s;
            }
        }
        p *= 10.0;
    }
    p
}

pub fn snap(q: f64) -> f64 {
    if (q - q.round()).abs() < 1e-9 {
        q.round()
    } else {
        q
    }
}

// Extend [lo, hi] outward to multiples of `s`.
pub fn nice_domain(lo: f64, hi: f64, s: f64) -> (f64, f64) {
    (snap(lo / s).floor() * s, snap(hi / s).ceil() * s)
}

// Multiples of `s` inside [lo, hi].
pub fn ticks_in(lo: f64, hi: f64, s: f64) -> Vec<f64> {
    let (a, b) = if lo <= hi { (lo, hi) } else { (hi, lo) };
    let k0 = snap(a / s).ceil() as i64;
    let k1 = snap(b / s).floor() as i64;
    let mut out = Vec::new();
    let mut k = k0;
    while k <= k1 && out.len() < 1000 {
        let v = k as f64 * s;
        out.push(if v == 0.0 { 0.0 } else { v });
        k += 1;
    }
    out
}

pub fn decimals_of(s: f64) -> usize {
    for d in 0..12 {
        let x = s * 10f64.powi(d as i32);
        if (x - x.round()).abs() < 1e-6 * x.abs().max(1.0) {
            return d;
        }
    }
    12
}

fn fixed(v: f64, d: usize) -> String {
    let s = format!("{:.*}", d, v);
    if s.starts_with('-') && s[1..].chars().all(|c| c == '0' || c == '.') {
        return s[1..].to_string();
    }
    s
}

fn trim(s: String) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0').trim_end_matches('.').to_string();
        if t == "-0" {
            return "0".into();
        }
        return t;
    }
    s
}

pub fn fmt_with(v: f64, fmt: Option<&Fmt>) -> Option<String> {
    match fmt {
        Some(Fmt::Decimal(n)) => Some(fixed(v, *n)),
        Some(Fmt::Percent(n)) => Some(format!("{}%", fixed(v * 100.0, *n))),
        _ => None,
    }
}

// A tick label on a numeric axis with step `s`.
pub fn fmt_tick(v: f64, s: f64, fmt: Option<&Fmt>) -> String {
    if let Some(x) = fmt_with(v, fmt) {
        return x;
    }
    trim(fixed(v, decimals_of(s)))
}

// A data value (tooltips, titles).
pub fn fmt_value(v: f64, fmt: Option<&Fmt>) -> String {
    if let Some(x) = fmt_with(v, fmt) {
        return x;
    }
    f4(v)
}

pub const MONTHS: [&str; 12] = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

pub fn fmt_date(days: f64) -> String {
    let (y, m, d) = civil_from_days(days.floor() as i64);
    format!("{} {} {}", MONTHS[(m - 1) as usize], d, y)
}

pub fn fmt_month(days: f64) -> String {
    let (y, m, _) = civil_from_days(days.floor() as i64);
    format!("{} {}", MONTHS[(m - 1) as usize], y)
}

// Charts: |chart| (bars, lines, areas, dots, bubbles, bands, marks, axes;
// cartesian or radial) and |pie| (slices). A chart lays out and paints its
// own series children; they are not rendered as ordinary nodes.

mod cart;
pub mod model;
mod pie;
mod radial;
pub mod scale;

use crate::compile::Ctx;
use crate::diag::Diag;
use crate::font::Family;
use crate::render::Out;
use crate::util::{f4, xml_escape};
use std::cell::RefCell;
use std::collections::HashMap;

// Chart text sizes: ticks/labels/tips 12 normal, legend 12 semibold, title 15 semibold.
pub const FS: f64 = 12.0;

pub fn tw(s: &str) -> f64 {
    crate::font::text_width(Family::Sans, 400, FS, s)
}

pub fn tw_legend(s: &str) -> f64 {
    crate::font::text_width(Family::Sans, 600, FS, s)
}

pub fn tw_title(s: &str) -> f64 {
    crate::font::text_width(Family::Sans, 600, 15.0, s)
}

// One emitted element of a chart.
#[derive(Clone, Debug)]
pub enum El {
    // <g class="lini-node {cls}" style transform> [title] inner... kids... </g>
    G { cls: String, style: String, tx: f64, ty: f64, title: Option<String>, inner: Vec<String>, kids: Vec<El> },
    // <text class="lini-text {cls}" x y dy style>text</text>
    T { cls: String, x: f64, y: f64, style: String, text: String },
}

#[derive(Default, Clone, Debug)]
pub struct Flags {
    pub title: bool,
    pub text: bool,
    pub label: bool,
    pub legend: bool,
    pub tip: bool,
    pub hits: usize,
    pub line: bool,
    pub oval: bool,
    pub poly: bool,
}

#[derive(Default, Clone, Debug)]
pub struct Drawing {
    pub els: Vec<El>,
    pub flags: Flags,
    // content bounds relative to the chart centre
    pub bbox: Option<[f64; 4]>,
}

thread_local! {
    static CACHE: RefCell<HashMap<usize, Result<Drawing, Diag>>> = RefCell::new(HashMap::new());
}

// Is node `i` a chart or pie container this module paints?
pub fn is_chart(ctx: &Ctx, i: usize) -> bool {
    let l = ctx.comp[i].layout.as_str();
    l == "chart" || l == "pie"
}

fn default_size(ctx: &Ctx, i: usize) -> (f64, f64) {
    let pie = ctx.comp[i].layout == "pie";
    let radial = ctx.nodes[i].props.get("direction").and_then(model::ident).as_deref() == Some("radial");
    let (dw, dh) = if pie || radial { (280.0, 280.0) } else { (360.0, 220.0) };
    let c = &ctx.comp[i];
    (c.width.unwrap_or(dw), c.height.unwrap_or(dh))
}

// Size the chart (sets ctx.nodes[i].w / h). Children are not laid out by the core.
pub fn measure(ctx: &mut Ctx, i: usize) {
    let (w, h) = default_size(ctx, i);
    {
        let n = &mut ctx.nodes[i];
        n.w = w;
        n.h = h;
    }
    let res = draw(ctx, i, w, h);
    CACHE.with(|c| {
        c.borrow_mut().insert(i, res);
    });
}

fn draw(ctx: &Ctx, i: usize, w: f64, h: f64) -> Result<Drawing, Diag> {
    let ch = model::build(ctx, i)?;
    let mut d = if ch.pie {
        pie::draw(ctx, &ch, w, h)?
    } else if ch.dir == model::Dir::Radial {
        radial::draw(ctx, &ch, w, h)?
    } else {
        cart::draw(ctx, &ch, w, h)?
    };
    d.bbox = Some(bbox_of(&d.els));
    Ok(d)
}

// Content bounds of a chart (relative to its centre), for the viewBox.
pub fn content_bbox(i: usize) -> Option<[f64; 4]> {
    CACHE.with(|c| match c.borrow().get(&i) {
        Some(Ok(d)) => d.bbox,
        _ => None,
    })
}

fn bbox_of(els: &[El]) -> [f64; 4] {
    let mut b = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
    for e in els {
        if let El::T { cls, x, y, text, .. } = e {
            let w = if cls.contains("chart-title") {
                tw_title(text)
            } else if cls.contains("chart-legend") {
                tw_legend(text)
            } else {
                tw(text)
            };
            let h = if cls.contains("chart-title") { 15.0 } else { FS };
            b[0] = b[0].min(x - w / 2.0);
            b[2] = b[2].max(x + w / 2.0);
            b[1] = b[1].min(y - h / 2.0);
            b[3] = b[3].max(y + h / 2.0);
        }
    }
    b
}

// Paint the chart's inner elements (inside the node's <g>, at indent `ind`).
pub fn render(ctx: &Ctx, i: usize, ind: usize, s: &mut String, out: &mut Out) -> Result<(), Diag> {
    let d = CACHE.with(|c| c.borrow().get(&i).cloned());
    let d = match d {
        Some(r) => r?,
        None => return Ok(()),
    };
    for l in crate::render::shape_lines(ctx, i) {
        s.push_str(&" ".repeat(ind));
        s.push_str(&l);
        s.push('\n');
    }
    for e in &d.els {
        emit(e, ind, s, out);
    }
    let f = &d.flags;
    out.any_text = true;
    if f.line && !out.used_types.iter().any(|t| t == "line") {
        out.used_types.push("line".into());
    }
    if f.oval {
        out.extra_rules.push(("oval".into(), ".lini-oval { stroke-dasharray: none; }".into()));
    }
    if f.poly {
        out.extra_rules.push(("poly".into(), ".lini-poly { stroke-dasharray: none; }".into()));
    }
    if f.title {
        out.extra_rules.push(("chart-title".into(), ".lini-chart-title { font-size: 15px; font-weight: 600; }".into()));
    }
    if f.text {
        out.extra_rules.push(("chart-text".into(), ".lini-chart-text { font-size: 12px; font-weight: normal; }".into()));
    }
    if f.label {
        out.extra_rules.push(("chart-label".into(), ".lini-chart-label { font-size: 12px; font-weight: normal; }".into()));
        out.extra_rules.push(("chart-label-pe".into(), ".lini-chart-label { pointer-events: none; }".into()));
    }
    if f.legend {
        out.extra_rules.push(("chart-legend".into(), ".lini-chart-legend { font-size: 12px; font-weight: 600; }".into()));
    }
    if f.tip {
        out.extra_rules.push(("chart-tip".into(), ".lini-chart-tip { visibility: hidden; pointer-events: none; }".into()));
        for k in 0..f.hits {
            out.extra_rules.push(("chart-hit".into(), format!(".lini-hit-{}:hover ~ .lini-tip-{} {{ visibility: visible; }}", k, k)));
        }
    }
    Ok(())
}

fn use_vars(style: &str, out: &mut Out) {
    let mut rest = style;
    while let Some(p) = rest.find("var(--lini-") {
        let after = &rest[p + 11..];
        let end = after.find(')').unwrap_or(after.len());
        crate::style::use_var(&mut out.vars, &after[..end]);
        rest = &after[end..];
    }
}

fn emit(e: &El, ind: usize, s: &mut String, out: &mut Out) {
    let pad = " ".repeat(ind);
    match e {
        El::G { cls, style, tx, ty, title, inner, kids } => {
            use_vars(style, out);
            s.push_str(&pad);
            s.push_str(&format!("<g class=\"lini-node {}\"", cls));
            if !style.is_empty() {
                s.push_str(&format!(" style=\"{}\"", xml_escape(style)));
            }
            s.push_str(&format!(" transform=\"translate({},{})\">\n", f4(*tx), f4(*ty)));
            let ci = " ".repeat(ind + 2);
            if let Some(t) = title {
                s.push_str(&format!("{}<title>{}</title>\n", ci, xml_escape(t)));
            }
            for l in inner {
                s.push_str(&ci);
                s.push_str(l);
                s.push('\n');
            }
            for k in kids {
                emit(k, ind + 2, s, out);
            }
            s.push_str(&pad);
            s.push_str("</g>\n");
        }
        El::T { cls, x, y, style, text } => {
            use_vars(style, out);
            s.push_str(&pad);
            s.push_str(&format!("<text class=\"lini-text {}\" x=\"{}\" y=\"{}\" dy=\"0.358em\"", cls, f4(*x), f4(*y)));
            if !style.is_empty() {
                s.push_str(&format!(" style=\"{}\"", xml_escape(style)));
            }
            s.push_str(&format!(">{}</text>\n", xml_escape(text)));
        }
    }
}

// ------------------------------------------------------------ shared helpers

pub fn rect(x: f64, y: f64, w: f64, h: f64, r: f64) -> String {
    format!("<rect x=\"{}\" y=\"{}\" width=\"{}\" height=\"{}\" rx=\"{}\" ry=\"{}\"/>", f4(x), f4(y), f4(w), f4(h), f4(r), f4(r))
}

pub fn line_el(x1: f64, y1: f64, x2: f64, y2: f64, style: &str) -> El {
    El::G {
        cls: "lini-line".into(),
        style: style.into(),
        tx: 0.0,
        ty: 0.0,
        title: None,
        inner: vec![format!("<line x1=\"{}\" y1=\"{}\" x2=\"{}\" y2=\"{}\"/>", f4(x1), f4(y1), f4(x2), f4(y2))],
        kids: vec![],
    }
}

pub fn pts_str(pts: &[(f64, f64)]) -> String {
    pts.iter().map(|(x, y)| format!("{},{}", f4(*x), f4(*y))).collect::<Vec<_>>().join(" ")
}

// A polyline (or a <line> for two points).
pub fn path_el(pts: &[(f64, f64)], style: &str) -> El {
    if pts.len() == 2 {
        return line_el(pts[0].0, pts[0].1, pts[1].0, pts[1].1, style);
    }
    El::G {
        cls: "lini-line".into(),
        style: style.into(),
        tx: 0.0,
        ty: 0.0,
        title: None,
        inner: vec![format!("<polyline points=\"{}\"/>", pts_str(pts))],
        kids: vec![],
    }
}

pub fn poly_el(cls: &str, pts: &[(f64, f64)], style: &str, title: Option<String>) -> El {
    El::G {
        cls: format!("{}lini-poly", cls),
        style: style.into(),
        tx: 0.0,
        ty: 0.0,
        title,
        inner: vec![format!("<polygon points=\"{}\"/>", pts_str(pts))],
        kids: vec![],
    }
}

pub fn text_el(cls: &str, x: f64, y: f64, style: &str, text: &str) -> El {
    El::T { cls: cls.into(), x, y, style: style.into(), text: text.into() }
}

// A hover tip anchored at (ax, ay), kept inside the chart box.
pub fn tip_el(k: usize, ax: f64, ay: f64, text: &str, bounds: [f64; 4]) -> El {
    let w = tw(text) + 10.0;
    let h = 22.0;
    let mut x = ax + 7.0;
    let mut y = ay - 29.0;
    if x + w > bounds[2] {
        x = bounds[2] - w;
    }
    if x < bounds[0] {
        x = bounds[0];
    }
    if y + h > bounds[3] {
        y = bounds[3] - h;
    }
    if y < bounds[1] {
        y = bounds[1];
    }
    let cx = x + w / 2.0;
    let cy = y + h / 2.0;
    El::G {
        cls: format!("lini-chart-tip lini-tip-{} lini-block", k),
        style: String::new(),
        tx: 0.0,
        ty: 0.0,
        title: None,
        inner: vec![rect(x, y, w, h, 0.0)],
        kids: vec![
            El::G {
                cls: "lini-block".into(),
                style: "fill: var(--lini-tip-bg); stroke-width: 0".into(),
                tx: cx,
                ty: cy,
                title: None,
                inner: vec![rect(-w / 2.0, -h / 2.0, w, h, 3.0)],
                kids: vec![],
            },
            text_el("lini-chart-text", cx, cy, "fill: var(--lini-tip-fg)", text),
        ],
    }
}

// ------------------------------------------------------------ colours

pub const PALETTE: &[&str] = &["rose", "teal", "orange", "sky", "amber", "purple", "green", "blue", "lime", "gray"];
pub const HUES: &[&str] = &["red", "rose", "orange", "amber", "lime", "green", "teal", "sky", "blue", "purple", "gray"];

pub fn hue(k: usize) -> &'static str {
    PALETTE[k % PALETTE.len()]
}

// The hue of a palette colour "var(--lini-sky-soft)" → "sky".
pub fn hue_of(css: &str) -> Option<String> {
    let inner = css.strip_prefix("var(--lini-")?.strip_suffix(')')?;
    let base = inner.split('-').next()?;
    if HUES.contains(&base) {
        let rest = &inner[base.len()..];
        if rest.is_empty() || matches!(rest, "-wash" | "-soft" | "-deep" | "-ink") {
            return Some(base.to_string());
        }
    }
    None
}

// The stroke derived from a fill: the hue's deep tier, else the fill itself.
pub fn deep_of(css: &str) -> String {
    match hue_of(css) {
        Some(h) => format!("var(--lini-{}-deep)", h),
        None => css.to_string(),
    }
}

// CSS text of a colour term (vars are registered when the style is emitted).
pub fn color_term(t: &crate::ast::Term) -> Option<String> {
    let mut tmp = Vec::new();
    match t {
        crate::ast::Term::Ident(s, _) if s == "auto" => None,
        _ => crate::style::color_css(t, &mut tmp, t.span()).ok(),
    }
}

// Entry k of a colour list (a single value applies to every entry).
pub fn color_at(v: &Option<crate::ast::Value>, k: usize) -> Option<String> {
    let v = v.as_ref()?;
    let g = if v.groups.len() == 1 { v.groups.first()? } else { v.groups.get(k)? };
    color_term(g.first()?)
}

pub fn is_list(v: &Option<crate::ast::Value>) -> bool {
    v.as_ref().map(|v| v.groups.len() > 1).unwrap_or(false)
}

pub fn raw_term(v: &Option<crate::ast::Value>) -> Option<String> {
    let v = v.as_ref()?;
    let t = crate::style::single_term(v)?;
    match t {
        crate::ast::Term::Ident(s, _) => Some(s.clone()),
        _ => color_term(t),
    }
}

// Cartesian charts: a plot rectangle with value axes, a category or numeric
// x axis, and the series painted into it.

use super::model::*;
use super::scale::*;
use super::*;
use crate::ast::Term;
use crate::compile::Ctx;
use crate::diag::Diag;
use crate::eval::EV;

#[derive(Clone, Debug)]
pub struct VAxis {
    pub ax: Option<usize>, // index into ch.axes
    pub right: bool,       // right (column) / top (row) side
    pub lo: f64,
    pub hi: f64,
    pub log: bool,
    pub ticks: Vec<f64>,
    pub labels: Vec<String>,
    pub title: Option<String>,
    pub gridlines: bool,
}

impl VAxis {
    pub fn frac(&self, v: f64) -> f64 {
        if self.log {
            let a = self.lo.log10();
            let b = self.hi.log10();
            (v.max(1e-300).log10() - a) / (b - a)
        } else {
            (v - self.lo) / (self.hi - self.lo)
        }
    }
}

pub struct Geo {
    pub l: f64,
    pub r: f64,
    pub t: f64,
    pub b: f64,
    pub horiz: bool,
}

impl Geo {
    // position along the value direction
    pub fn vpos(&self, a: &VAxis, v: f64) -> f64 {
        let f = a.frac(v);
        if self.horiz {
            self.l + f * (self.r - self.l)
        } else {
            self.b - f * (self.b - self.t)
        }
    }
}

pub fn eval_fn(ctx: &Ctx, t: &Term, x: f64, u: Option<f64>) -> Result<f64, Diag> {
    let mut locals = std::collections::HashMap::new();
    locals.insert("x".to_string(), EV::Num(x));
    if let Some(u) = u {
        locals.insert("u".to_string(), EV::Num(u));
    }
    let r = ctx.sheet.env.eval_term(t, &locals).map_err(|e| Diag::error("layout", &e.message, e.span))?;
    Ok(r.num().unwrap_or(0.0))
}

fn axis_labels(ax: Option<&Axis>, ch: &Chart, ticks: &[f64], step: f64, time: bool) -> Vec<String> {
    let unit = ax.map(|a| a.unit.clone()).unwrap_or_default();
    let fmt = ax.and_then(|a| a.format.clone()).or_else(|| ch.format.clone());
    ticks
        .iter()
        .map(|&v| {
            if time {
                fmt_month(v)
            } else {
                format!("{}{}", fmt_tick(v, step, fmt.as_ref()), unit)
            }
        })
        .collect()
}

// Domain and ticks of a value axis from the values it must show.
fn value_axis(ch: &Chart, ax: Option<usize>, right: bool, vals: &[f64]) -> VAxis {
    let a = ax.map(|k| &ch.axes[k]);
    let log = a.map(|a| a.log).unwrap_or(false);
    let (lo, hi, ticks, step);
    if log {
        let pos: Vec<f64> = vals.iter().cloned().filter(|v| *v > 0.0).collect();
        let mn = pos.iter().cloned().fold(f64::INFINITY, f64::min);
        let mx = pos.iter().cloned().fold(f64::NEG_INFINITY, f64::max);
        let (mn, mx) = if mn.is_finite() { (mn, mx) } else { (1.0, 10.0) };
        let (l, h) = match a.and_then(|a| a.range) {
            Some(r) => r,
            None => (10f64.powf(mn.log10().floor()), 10f64.powf(mx.log10().ceil())),
        };
        let (l, h) = if l == h { (l, l * 10.0) } else { (l, h) };
        lo = l;
        hi = h;
        let mut t = Vec::new();
        let mut e = lo.log10().ceil() as i32;
        while 10f64.powi(e) <= hi * (1.0 + 1e-9) && t.len() < 100 {
            t.push(10f64.powi(e));
            e += 1;
        }
        ticks = t;
        step = 1.0;
    } else {
        match a.and_then(|a| a.range) {
            Some((l, h)) => {
                lo = l;
                hi = h;
                step = match a.and_then(|a| a.step.clone()) {
                    Some(StepSpec::Num(s)) if s > 0.0 => s,
                    _ => nice_step((h - l).abs()),
                };
                ticks = ticks_in(l, h, step);
            }
            None => {
                let mut mn = 0.0f64;
                let mut mx = 0.0f64;
                for &v in vals {
                    mn = mn.min(v);
                    mx = mx.max(v);
                }
                let s = match a.and_then(|a| a.step.clone()) {
                    Some(StepSpec::Num(s)) if s > 0.0 => s,
                    _ => nice_step(mx - mn),
                };
                let (l, h) = if mx == mn { (0.0, 1.0) } else { nice_domain(mn, mx, s) };
                lo = l;
                hi = h;
                step = if mx == mn { nice_step(1.0) } else { s };
                ticks = ticks_in(lo, hi, step);
            }
        }
    }
    let mut ticks = ticks;
    if let Some(t) = a.and_then(|a| a.ticks.clone()) {
        ticks = t;
    }
    if a.map(|a| a.ticks_none).unwrap_or(false) {
        ticks = vec![];
    }
    let labels = if log {
        ticks.iter().map(|v| format!("{}{}", fmt_tick(*v, 1.0, a.and_then(|a| a.format.as_ref()).or(ch.format.as_ref())), a.map(|a| a.unit.clone()).unwrap_or_default())).collect()
    } else {
        axis_labels(a, ch, &ticks, step, false)
    };
    VAxis {
        ax,
        right,
        lo,
        hi,
        log,
        ticks,
        labels,
        title: a.and_then(|a| a.title.clone()),
        gridlines: a.map(|a| a.gridlines).unwrap_or(true),
    }
}

struct XNum {
    lo: f64,
    hi: f64,
    ticks: Vec<f64>,
    labels: Vec<String>,
    time: bool,
}

fn month_ticks(lo: f64, hi: f64, every: i64) -> Vec<f64> {
    let (y0, m0, _) = civil_from_days(lo.floor() as i64);
    let mut out = Vec::new();
    let mut y = y0;
    let mut m = m0;
    for _ in 0..2000 {
        let d = days_from_civil(y, m, 1) as f64;
        if d > hi + 1e-9 {
            break;
        }
        if d >= lo - 1e-9 && ((y * 12 + m - 1) % every == 0) {
            out.push(d);
        }
        m += 1;
        if m > 12 {
            m = 1;
            y += 1;
        }
    }
    out
}

pub fn draw(ctx: &Ctx, ch: &Chart, w: f64, h: f64) -> Result<Drawing, Diag> {
    let horiz = ch.dir == Dir::Row;
    let mut flags = Flags::default();
    let c = ch.clearance;
    let g = ch.gap;
    let (cl, cr, ct, cb) = (-w / 2.0, w / 2.0, -h / 2.0, h / 2.0);
    // ---- categories or a numeric x
    let numeric_x = ch.categories.is_none() && ch.series.iter().any(|s| s.points || !s.fns.is_empty() || s.kind == Kind::Bubble);
    let implicit_cats = ch.categories.is_none() && !numeric_x;
    let cats: Vec<String> = match &ch.categories {
        Some(c) => c.clone(),
        None => {
            if numeric_x {
                vec![]
            } else {
                let n = ch.series.iter().map(|s| s.vals.len()).max().unwrap_or(0);
                (1..=n).map(|k| k.to_string()).collect()
            }
        }
    };
    // ---- axes: which declared axes are value axes, which is the x axis
    let is_cross = |a: &Axis| -> bool {
        match a.side.as_deref() {
            Some("bottom") | Some("top") => !horiz,
            Some("left") | Some("right") => horiz,
            _ => false,
        }
    };
    let x_axis: Option<usize> = ch.axes.iter().position(|a| is_cross(a));
    let mut vaxes_idx: Vec<usize> = (0..ch.axes.len()).filter(|&k| !is_cross(&ch.axes[k])).collect();
    // band / mark axes that are the x axis by id
    let default_v: Option<usize> = vaxes_idx.first().cloned();
    let series_axis = |s: &Series| -> Option<usize> {
        match &s.axis {
            Some(id) => ch.axes.iter().position(|a| a.id.as_deref() == Some(id.as_str())),
            None => default_v,
        }
    };
    // ---- numeric x domain
    let mut xnum: Option<XNum> = None;
    if numeric_x {
        let xa = x_axis.map(|k| &ch.axes[k]);
        let time = ch.series.iter().any(|s| s.time_x) || xa.map(|a| a.range_time).unwrap_or(false);
        let (lo, hi) = match xa.and_then(|a| a.range) {
            Some(r) => r,
            None => {
                let mut mn = f64::INFINITY;
                let mut mx = f64::NEG_INFINITY;
                for s in &ch.series {
                    for p in &s.pts {
                        mn = mn.min(p.0);
                        mx = mx.max(p.0);
                    }
                    if let Some(a) = s.at {
                        mn = mn.min(a.0);
                        mx = mx.max(a.0);
                    }
                }
                if !mn.is_finite() {
                    (0.0, 1.0)
                } else if ch.series.iter().any(|s| s.kind == Kind::Bubble) {
                    let pad = (mx - mn) * 0.1;
                    (mn - pad, mx + pad)
                } else if mn == mx {
                    (mn - 1.0, mx + 1.0)
                } else {
                    (mn, mx)
                }
            }
        };
        let (ticks, labels) = if time {
            let every = match xa.and_then(|a| a.step.clone()) {
                Some(StepSpec::Cal(s)) if s == "month" => 1,
                Some(StepSpec::Cal(s)) if s == "quarter" => 3,
                Some(StepSpec::Cal(s)) if s == "year" => 12,
                _ => 1,
            };
            let t = month_ticks(lo, hi, every);
            let l = t.iter().map(|v| fmt_month(*v)).collect();
            (t, l)
        } else {
            let step = match xa.and_then(|a| a.step.clone()) {
                Some(StepSpec::Num(s)) if s > 0.0 => s,
                _ => nice_step((hi - lo).abs()),
            };
            let mut t = ticks_in(lo, hi, step);
            if let Some(tt) = xa.and_then(|a| a.ticks.clone()) {
                t = tt;
            }
            if xa.map(|a| a.ticks_none).unwrap_or(false) {
                t = vec![];
            }
            let l = axis_labels(xa, ch, &t, step, false);
            (t, l)
        };
        xnum = Some(XNum { lo, hi, ticks, labels, time });
    }
    // ---- sample formulas
    let mut series_pts: Vec<Vec<(f64, f64)>> = vec![];
    for s in &ch.series {
        if !s.fns.is_empty() {
            let xn = xnum.as_ref().unwrap();
            let n = ch.samples.max(2);
            let mut pts = Vec::new();
            if s.fns.len() == 1 || ch.bands.is_empty() {
                for k in 0..n {
                    let x = xn.lo + (xn.hi - xn.lo) * k as f64 / (n - 1) as f64;
                    let y = eval_fn(ctx, &s.fns[0], x, None)?;
                    pts.push((x, y));
                }
            } else {
                for (bi, b) in ch.bands.iter().enumerate() {
                    let f = match s.fns.get(bi) {
                        Some(f) => f,
                        None => s.fns.last().unwrap(),
                    };
                    for k in 0..n {
                        let u = k as f64 / (n - 1) as f64;
                        let x = b.range.0 + (b.range.1 - b.range.0) * u;
                        let y = eval_fn(ctx, f, x, Some(u))?;
                        pts.push((x, y));
                    }
                }
            }
            series_pts.push(pts);
        } else if s.points {
            series_pts.push(s.pts.clone());
        } else {
            series_pts.push(vec![]);
        }
    }
    // ---- value axes
    if vaxes_idx.is_empty() {
        vaxes_idx = vec![];
    }
    let mut vax: Vec<VAxis> = Vec::new();
    let vlist: Vec<Option<usize>> = if vaxes_idx.is_empty() { vec![None] } else { vaxes_idx.iter().map(|k| Some(*k)).collect() };
    let stacked = ch.bars_mode == "stacked";
    for &ak in &vlist {
        let mut vals: Vec<f64> = Vec::new();
        let mut stack_pos = vec![0.0; cats.len()];
        let mut stack_neg = vec![0.0; cats.len()];
        for (si, s) in ch.series.iter().enumerate() {
            let sa = series_axis(s);
            if sa != ak && !(ak.is_none() && sa.is_none()) {
                continue;
            }
            if s.kind == Kind::Bars && stacked && !s.points {
                for (k, v) in s.vals.iter().enumerate() {
                    if k < cats.len() {
                        if *v >= 0.0 {
                            stack_pos[k] += v;
                        } else {
                            stack_neg[k] += v;
                        }
                    }
                }
                continue;
            }
            vals.extend(s.vals.iter().cloned());
            for p in &series_pts[si] {
                vals.push(p.1);
            }
            if let Some(a) = s.at {
                vals.push(a.1);
            }
            if let Some(b) = s.baseline {
                vals.push(b);
            }
        }
        vals.extend(stack_pos.iter().cloned());
        vals.extend(stack_neg.iter().cloned());
        let right = match ak.and_then(|k| ch.axes[k].side.clone()).as_deref() {
            Some("right") | Some("top") => true,
            _ => false,
        };
        vax.push(value_axis(ch, ak, right, &vals));
    }
    let vax_of = |s: &Series| -> usize {
        let sa = series_axis(s);
        vlist.iter().position(|a| *a == sa).unwrap_or(0)
    };
    // ---- legend entries
    let named: Vec<usize> = (0..ch.series.len()).filter(|&k| ch.series[k].name.is_some()).collect();
    let legend = named.len() >= 2;
    // ---- frame
    let mut region_top = ct + 8.0;
    let mut title_y = 0.0;
    if ch.title.is_some() {
        title_y = region_top + 10.5;
        region_top += 18.0 + g;
    }
    let region_bottom = if legend { cb - 16.4 - g } else { cb - 8.0 };
    // side labels
    let (mut left_w, mut right_w) = (None::<f64>, None::<f64>);
    let mut grow = |slot: &mut Option<f64>, wv: f64| {
        *slot = Some(slot.unwrap_or(0.0).max(wv));
    };
    let mut top_title = false;
    let mut bottom_title: Option<String> = None;
    if horiz {
        // categories on the left, values along the bottom
        for cname in &cats {
            grow(&mut left_w, tw(cname));
        }
        if let Some(xk) = x_axis {
            if ch.axes[xk].title.is_some() {
                top_title = true;
            }
        }
        for a in &vax {
            if a.title.is_some() && bottom_title.is_none() {
                bottom_title = a.title.clone();
            }
        }
    } else {
        for a in &vax {
            for l in &a.labels {
                if a.right {
                    grow(&mut right_w, tw(l));
                } else {
                    grow(&mut left_w, tw(l));
                }
            }
            if a.title.is_some() {
                top_title = true;
            }
        }
        if let Some(xk) = x_axis {
            bottom_title = ch.axes[xk].title.clone();
        }
    }
    let pl = match left_w {
        Some(wv) => cl + 4.0 + wv + c,
        None => cl + 12.0,
    };
    let pr = match right_w {
        Some(wv) => cr - 4.0 - wv - c,
        None => cr - 12.0,
    };
    let pt = if top_title { region_top + 16.8 + c } else { region_top };
    let band_labels = ch.bands.iter().any(|b| b.name.is_some());
    let mut stack = c + 14.8;
    if band_labels {
        stack += 12.0;
    }
    if bottom_title.is_some() {
        stack += 22.8;
    }
    let pb = region_bottom - stack;
    let geo = Geo { l: pl, r: pr, t: pt, b: pb, horiz };
    let bounds = [cl, ct, cr, cb];
    // ---- positions
    let ncat = cats.len().max(1) as f64;
    let band_w = if horiz { (pb - pt) / ncat } else { (pr - pl) / ncat };
    let cat_pos = |k: usize| -> f64 {
        if horiz {
            pt + (k as f64 + 0.5) * band_w
        } else {
            pl + (k as f64 + 0.5) * band_w
        }
    };
    let xpos = |x: f64| -> f64 {
        let xn = xnum.as_ref().unwrap();
        pl + (x - xn.lo) / (xn.hi - xn.lo) * (pr - pl)
    };
    // point → (px, py)
    let to_xy = |s: &Series, k: usize, v: f64, xv: Option<f64>| -> (f64, f64) {
        let a = &vax[vax_of(s)];
        let along = match xv {
            Some(x) => xpos(x),
            None => cat_pos(k),
        };
        let vp = geo.vpos(a, v);
        if horiz {
            (vp, along)
        } else {
            (along, vp)
        }
    };
    let mut els: Vec<El> = Vec::new();
    // ---- bands
    for b in &ch.bands {
        let fill = color_at(&b.fill, 0).unwrap_or_else(|| "var(--lini-gray)".into());
        let (x0, x1) = (xpos(b.range.0), xpos(b.range.1));
        let (a, bb) = (x0.min(x1), x0.max(x1));
        let bw = bb - a;
        let bh = pb - pt;
        els.push(El::G {
            cls: "lini-block".into(),
            style: format!("fill: {}; stroke-width: 0; opacity: 0.15", fill),
            tx: (a + bb) / 2.0,
            ty: (pt + pb) / 2.0,
            title: None,
            inner: vec![rect(-bw / 2.0, -bh / 2.0, bw, bh, 0.0)],
            kids: vec![],
        });
    }
    // ---- gridlines
    let grid = "stroke: var(--lini-grid); stroke-width: 1";
    for a in &vax {
        if !a.gridlines {
            continue;
        }
        for &t in &a.ticks {
            let p = geo.vpos(a, t);
            flags.line = true;
            if horiz {
                els.push(line_el(p, pt, p, pb, grid));
            } else {
                els.push(line_el(pl, p, pr, p, grid));
            }
        }
    }
    if let Some(xn) = &xnum {
        let gl = x_axis.map(|k| ch.axes[k].gridlines).unwrap_or(true);
        if gl {
            for &t in &xn.ticks {
                let p = xpos(t);
                flags.line = true;
                els.push(line_el(p, pt, p, pb, grid));
            }
        }
    }
    // ---- series
    let mut hits: Vec<(f64, f64, String)> = Vec::new();
    let mut labels: Vec<(f64, f64, f64, String)> = Vec::new(); // anchor x, y, radius, text
    let show_tips = ch.tooltip != "none";
    let show_labels = ch.tooltip == "auto" || ch.tooltip == "always";
    let fmt = ch.format.clone();
    let tip_text = |s: &Series, k: usize, v: f64, xv: Option<f64>, time: bool| -> String {
        let val = fmt_value(v, fmt.as_ref());
        match xv {
            Some(x) => {
                let xs = if time { fmt_date(x) } else { fmt_value(x, None) };
                match &s.name {
                    Some(n) => format!("{}: {}, {}", n, xs, val),
                    None => format!("{}, {}", xs, val),
                }
            }
            None => {
                if implicit_cats {
                    match &s.name {
                        Some(n) => format!("{}: {}", n, val),
                        None => val,
                    }
                } else {
                    let cat = cats.get(k).cloned().unwrap_or_default();
                    match &s.name {
                        Some(n) => format!("{} · {}: {}", cat, n, val),
                        None => format!("{}: {}", cat, val),
                    }
                }
            }
        }
    };
    let time_x = xnum.as_ref().map(|x| x.time).unwrap_or(false);
    // areas first
    let order: Vec<usize> = {
        let mut o: Vec<usize> = Vec::new();
        for kind in [Kind::Area, Kind::Bars, Kind::Line, Kind::Dots, Kind::Bubble] {
            for (k, s) in ch.series.iter().enumerate() {
                if s.kind == kind {
                    o.push(k);
                }
            }
        }
        o
    };
    let bar_series: Vec<usize> = (0..ch.series.len()).filter(|&k| ch.series[k].kind == Kind::Bars).collect();
    let nb = bar_series.len().max(1) as f64;
    let overlay = ch.bars_mode == "overlay";
    let mut stack_base_pos = vec![0.0; cats.len()];
    let mut stack_base_neg = vec![0.0; cats.len()];
    // bars are drawn category-major
    let mut bars_done = false;
    for &si in &order {
        let s = &ch.series[si];
        let hue_name = hue(s.index);
        match s.kind {
            Kind::Area | Kind::Line => {
                let color = series_line_color(s);
                let pts: Vec<(f64, f64)> = if s.points || !s.fns.is_empty() {
                    series_pts[si].iter().map(|p| to_xy(s, 0, p.1, Some(p.0))).collect()
                } else {
                    s.vals.iter().enumerate().map(|(k, v)| to_xy(s, k, *v, None)).collect()
                };
                let path = curve_points(&pts, &s.curve, horiz);
                if s.kind == Kind::Area {
                    let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{}-soft)", hue_name));
                    let base_v = s.baseline.unwrap_or(0.0);
                    let a = &vax[vax_of(s)];
                    let bp = geo.vpos(a, base_v);
                    let mut poly = path.clone();
                    if let (Some(first), Some(last)) = (path.first().cloned(), path.last().cloned()) {
                        if horiz {
                            poly.push((bp, last.1));
                            poly.push((bp, first.1));
                        } else {
                            poly.push((last.0, bp));
                            poly.push((first.0, bp));
                        }
                    }
                    flags.poly = true;
                    els.push(poly_el("", &poly, &format!("fill: {}; stroke: none; stroke-width: 0; opacity: 0.82", fill), None));
                    let lc = match (&s.stroke, raw_term(&s.fill)) {
                        (Some(_), _) => color_at(&s.stroke, 0).unwrap_or_else(|| deep_of(&fill)),
                        _ => deep_of(&fill),
                    };
                    flags.line = true;
                    els.push(path_el(&path, &line_style(&lc, s)));
                } else {
                    flags.line = true;
                    els.push(path_el(&path, &line_style(&color, s)));
                }
                // markers
                if let Some(m) = &s.marker {
                    let r = if m == "circle" { 5.5 } else { 2.5 };
                    let raw: Vec<(Option<f64>, f64, usize)> = if s.points {
                        s.pts.iter().enumerate().map(|(k, p)| (Some(p.0), p.1, k)).collect()
                    } else if s.fns.is_empty() {
                        s.vals.iter().enumerate().map(|(k, v)| (None, *v, k)).collect()
                    } else {
                        vec![]
                    };
                    for (xv, v, k) in raw {
                        let (px, py) = to_xy(s, k, v, xv);
                        let hk = hits.len();
                        let tt = tip_text(s, k, v, xv, time_x);
                        flags.oval = true;
                        let cls = if show_tips { format!("lini-hit-{} lini-oval", hk) } else { "lini-oval".to_string() };
                        els.push(El::G {
                            cls,
                            style: format!("fill: {}; stroke: none; stroke-width: 0", color),
                            tx: px,
                            ty: py,
                            title: if show_tips { Some(tt.clone()) } else { None },
                            inner: vec![format!("<ellipse cx=\"0\" cy=\"0\" rx=\"{}\" ry=\"{}\"/>", f4(r), f4(r))],
                            kids: vec![],
                        });
                        if show_tips {
                            hits.push((px, py, tt));
                        }
                        if show_labels {
                            if let Some(l) = s.labels.get(k) {
                                if !l.is_empty() {
                                    labels.push((px, py, r, l.clone()));
                                }
                            }
                        }
                    }
                }
            }
            Kind::Bars => {
                if bars_done {
                    continue;
                }
                bars_done = true;
                let group = 0.72 * band_w;
                let slot = if stacked || overlay { group } else { group / nb };
                let thick = 0.9 * slot;
                for k in 0..cats.len() {
                    for (bk, &bsi) in bar_series.iter().enumerate() {
                        let s = &ch.series[bsi];
                        let v = match s.vals.get(k) {
                            Some(v) => *v,
                            None => continue,
                        };
                        let a = &vax[vax_of(s)];
                        let center = if stacked || overlay { cat_pos(k) } else { cat_pos(k) - group / 2.0 + slot * (bk as f64 + 0.5) };
                        let (v0, v1) = if stacked {
                            if v >= 0.0 {
                                let b = stack_base_pos[k];
                                stack_base_pos[k] += v;
                                (b, b + v)
                            } else {
                                let b = stack_base_neg[k];
                                stack_base_neg[k] += v;
                                (b, b + v)
                            }
                        } else {
                            (0.0, v)
                        };
                        let p0 = geo.vpos(a, v0);
                        let p1 = geo.vpos(a, v1);
                        let (fill, stroke, sw) = bar_colors(s, k);
                        let len = (p1 - p0).abs();
                        let mid = (p0 + p1) / 2.0;
                        let (iw, ih, cx, cy) = if horiz { (len - sw, thick - sw, mid, center) } else { (thick - sw, len - sw, center, mid) };
                        let mut style = format!("fill: {}", fill);
                        match &stroke {
                            Some(st) => style.push_str(&format!("; stroke: {}", st)),
                            None => style.push_str("; stroke-width: 0"),
                        }
                        if overlay {
                            style.push_str("; opacity: 0.6");
                        }
                        let hk = hits.len();
                        let tt = tip_text(s, k, v, None, false);
                        let radius = crate::style::value_num(&ctx.sheet.env, ctx.nodes[s.node].props.get("radius").unwrap_or(&crate::ast::Value { groups: vec![], span: Default::default() })).unwrap_or(2.0);
                        els.push(El::G {
                            cls: if show_tips { format!("lini-hit-{} lini-block", hk) } else { "lini-block".into() },
                            style,
                            tx: cx,
                            ty: cy,
                            title: if show_tips { Some(tt.clone()) } else { None },
                            inner: vec![rect(-iw / 2.0, -ih / 2.0, iw, ih, radius)],
                            kids: vec![],
                        });
                        if show_tips {
                            hits.push((cx, cy, tt));
                        }
                        if show_labels {
                            if let Some(l) = s.labels.get(k) {
                                if !l.is_empty() {
                                    // anchor at the bar end
                                    let (ex, ey) = if horiz { (p1.max(p0), cy) } else { (cx, p1.min(p0)) };
                                    labels.push((ex, ey, -1.0, l.clone()));
                                }
                            }
                        }
                    }
                }
            }
            Kind::Dots => {
                let base = format!("var(--lini-{}-ink)", hue_name);
                let n = if s.points { s.pts.len() } else { s.vals.len() };
                for k in 0..n {
                    let (xv, v) = if s.points { (Some(s.pts[k].0), s.pts[k].1) } else { (None, s.vals[k]) };
                    let (px, py) = to_xy(s, k, v, xv);
                    let dot_fill = if is_list(&s.fill) {
                        color_at(&s.fill, k).unwrap_or_else(|| base.clone())
                    } else {
                        match (&s.stroke, &s.fill) {
                            (Some(_), _) if !is_list(&s.stroke) => raw_term(&s.stroke).unwrap_or_else(|| base.clone()),
                            (_, Some(_)) => raw_term(&s.fill).unwrap_or_else(|| base.clone()),
                            _ => base.clone(),
                        }
                    };
                    let style = if is_list(&s.stroke) {
                        let st = color_at(&s.stroke, k).unwrap_or_else(|| deep_of(&dot_fill));
                        format!("fill: {}; stroke: {}; stroke-width: 2", dot_fill, st)
                    } else {
                        format!("fill: {}; stroke: none; stroke-width: 0", dot_fill)
                    };
                    let hk = hits.len();
                    let tt = tip_text(s, k, v, xv, time_x);
                    flags.oval = true;
                    els.push(El::G {
                        cls: if show_tips { format!("lini-hit-{} lini-oval", hk) } else { "lini-oval".into() },
                        style,
                        tx: px,
                        ty: py,
                        title: if show_tips { Some(tt.clone()) } else { None },
                        inner: vec!["<ellipse cx=\"0\" cy=\"0\" rx=\"2.5\" ry=\"2.5\"/>".into()],
                        kids: vec![],
                    });
                    if show_tips {
                        hits.push((px, py, tt));
                    }
                    if show_labels {
                        if let Some(l) = s.labels.get(k) {
                            if !l.is_empty() {
                                labels.push((px, py, 2.5, l.clone()));
                            }
                        }
                    }
                }
            }
            Kind::Bubble => {}
        }
    }
    // bubbles: radius ∝ √value, the largest 0.14 of the plot's short side
    let bubbles: Vec<usize> = (0..ch.series.len()).filter(|&k| ch.series[k].kind == Kind::Bubble).collect();
    if !bubbles.is_empty() {
        let vmax = bubbles.iter().map(|&k| ch.series[k].value.unwrap_or(0.0)).fold(0.0f64, f64::max);
        let rmax = 0.14 * (pr - pl).min(pb - pt);
        for &bk in &bubbles {
            let s = &ch.series[bk];
            let (ax, ay) = s.at.unwrap_or((0.0, 0.0));
            let v = s.value.unwrap_or(0.0);
            let r = if vmax > 0.0 { rmax * (v / vmax).sqrt() } else { 0.0 };
            let (px, py) = to_xy(s, 0, ay, Some(ax));
            let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{})", hue(s.index)));
            let hk = hits.len();
            let tt = match &s.name {
                Some(n) => format!("{}: {}", n, fmt_value(v, fmt.as_ref())),
                None => fmt_value(v, fmt.as_ref()),
            };
            flags.oval = true;
            els.push(El::G {
                cls: if show_tips { format!("lini-hit-{} lini-oval", hk) } else { "lini-oval".into() },
                style: format!("fill: {}; stroke: none; stroke-width: 0", fill),
                tx: px,
                ty: py,
                title: if show_tips { Some(tt.clone()) } else { None },
                inner: vec![format!("<ellipse cx=\"0\" cy=\"0\" rx=\"{}\" ry=\"{}\"/>", f4(r), f4(r))],
                kids: vec![],
            });
            if show_tips {
                hits.push((px, py, tt));
            }
            if show_labels {
                if let Some(n) = &s.name {
                    labels.push((px, py, r, n.clone()));
                }
            }
        }
    }
    // ---- marks
    for m in &ch.marks {
        let ak = ch.axes.iter().position(|a| a.id.as_deref() == m.axis.as_deref());
        let on_x = match ak {
            Some(k) => is_cross(&ch.axes[k]),
            None => false,
        };
        let stroke = color_at(&m.stroke, 0).unwrap_or_else(|| "var(--lini-muted)".into());
        let sw = m.stroke_width.unwrap_or(1.5);
        let mut style = format!("stroke: {}; stroke-width: {}", stroke, f4(sw));
        if let Some(st) = &m.stroke_style {
            if st != "solid" {
                if let Some(d) = crate::style::dasharray(st, sw) {
                    style.push_str(&format!("; stroke-dasharray: {}", d));
                }
            }
        }
        let tcolor = color_at(&m.color, 0).or_else(|| color_at(&m.stroke, 0)).unwrap_or_else(|| "var(--lini-muted)".into());
        flags.line = true;
        if on_x != horiz {
            // across the x direction: a vertical line
            let x = if on_x { xpos(m.at) } else { geo.vpos(&vax[vlist.iter().position(|a| *a == ak).unwrap_or(0)], m.at) };
            els.push(line_el(x, pt, x, pb, &style));
            if let Some(n) = &m.name {
                flags.text = true;
                els.push(text_el("lini-chart-text", x + 6.0 + tw(n) / 2.0, pt + 10.8, &format!("fill: {}", tcolor), n));
            }
        } else {
            let a = &vax[vlist.iter().position(|a| *a == ak).unwrap_or(0)];
            let y = geo.vpos(a, m.at);
            els.push(line_el(pl, y, pr, y, &style));
            if let Some(n) = &m.name {
                flags.text = true;
                els.push(text_el("lini-chart-text", pl + 6.0 + tw(n) / 2.0, y - 7.2, &format!("fill: {}", tcolor), n));
            }
        }
    }
    // ---- axis labels
    let muted = "fill: var(--lini-muted)";
    let tick_y = pb + c + 8.4;
    if horiz {
        // value axes along the bottom
        for a in &vax {
            for (t, l) in a.ticks.iter().zip(a.labels.iter()) {
                flags.text = true;
                els.push(text_el("lini-chart-text", geo.vpos(a, *t), tick_y, muted, l));
            }
        }
        for (k, cname) in cats.iter().enumerate() {
            flags.text = true;
            els.push(text_el("lini-chart-text", pl - c - tw(cname) / 2.0, cat_pos(k), muted, cname));
        }
    } else {
        for a in &vax {
            for (t, l) in a.ticks.iter().zip(a.labels.iter()) {
                let y = geo.vpos(a, *t);
                let x = if a.right { pr + c + tw(l) / 2.0 } else { pl - c - tw(l) / 2.0 };
                flags.text = true;
                els.push(text_el("lini-chart-text", x, y, muted, l));
            }
            if let Some(tt) = &a.title {
                let x = if a.right { pr - tw(tt) / 2.0 } else { pl + tw(tt) / 2.0 };
                flags.text = true;
                els.push(text_el("lini-chart-text", x, pt - c, muted, tt));
            }
        }
        if let Some(xn) = &xnum {
            for (t, l) in xn.ticks.iter().zip(xn.labels.iter()) {
                flags.text = true;
                els.push(text_el("lini-chart-text", xpos(*t), tick_y, muted, l));
            }
        } else {
            for (k, cname) in cats.iter().enumerate() {
                flags.text = true;
                els.push(text_el("lini-chart-text", cat_pos(k), tick_y, muted, cname));
            }
        }
    }
    if let Some(bt) = &bottom_title {
        flags.text = true;
        els.push(text_el("lini-chart-text", (pl + pr) / 2.0, region_bottom - 6.4, muted, bt));
    }
    // ---- band labels
    for b in &ch.bands {
        if let Some(n) = &b.name {
            let fill = color_at(&b.fill, 0).unwrap_or_else(|| "var(--lini-gray)".into());
            let (x0, x1) = (xpos(b.range.0), xpos(b.range.1));
            flags.text = true;
            els.push(text_el("lini-chart-text", (x0 + x1) / 2.0, tick_y + 16.8, &format!("fill: {}", fill), n));
        }
    }
    // ---- title
    if let Some(t) = &ch.title {
        flags.title = true;
        els.push(text_el("lini-chart-title", 0.0, title_y, "", t));
    }
    // ---- legend
    if legend {
        flags.legend = true;
        let ly = cb - 10.8;
        let items: Vec<(String, El)> = named
            .iter()
            .map(|&k| {
                let s = &ch.series[k];
                (s.name.clone().unwrap(), swatch(s))
            })
            .collect();
        legend_row(&mut els, items, ly);
    }
    // ---- labels
    for (x, y, r, t) in &labels {
        flags.label = true;
        let (lx, ly) = place_label(*x, *y, *r, t, &geo, c);
        els.push(text_el("lini-chart-label", lx, ly, muted, t));
    }
    // ---- tips
    if show_tips && !hits.is_empty() {
        flags.tip = true;
        flags.text = true;
        flags.hits = hits.len();
        for (k, (x, y, t)) in hits.iter().enumerate() {
            els.push(tip_el(k, *x, *y, t, bounds));
        }
    }
    Ok(Drawing { els, flags, bbox: None })
}

fn place_label(x: f64, y: f64, r: f64, t: &str, geo: &Geo, c: f64) -> (f64, f64) {
    let _ = t;
    if r < 0.0 {
        // bar end: above, else inside
        let above = y - c - 6.0;
        if above - 6.0 < geo.t {
            return (x, y + c + 6.0);
        }
        return (x, above);
    }
    let off = r + c + 6.0;
    let above = y - off;
    if above - 6.0 < geo.t {
        return (x, y + off);
    }
    (x, above)
}

pub fn legend_row(els: &mut Vec<El>, items: Vec<(String, El)>, ly: f64) {
    let mut total = 0.0;
    for (k, (name, _)) in items.iter().enumerate() {
        if k > 0 {
            total += 16.0;
        }
        total += 11.0 + 5.0 + tw_legend(name);
    }
    let mut x = -total / 2.0;
    for (name, sw) in items {
        let mut sw = sw;
        if let El::G { tx, ty, .. } = &mut sw {
            *tx = x + 5.5;
            *ty = ly;
        }
        els.push(sw);
        let w = tw_legend(&name);
        els.push(text_el("lini-chart-legend", x + 16.0 + w / 2.0, ly, "", &name));
        x += 16.0 + w + 16.0;
    }
}

pub fn swatch_filled(color: &str) -> El {
    El::G {
        cls: "lini-block".into(),
        style: format!("fill: {}; stroke-width: 0", color),
        tx: 0.0,
        ty: 0.0,
        title: None,
        inner: vec![rect(-5.5, -5.5, 11.0, 11.0, 2.0)],
        kids: vec![],
    }
}

pub fn swatch_outlined(fill: &str, stroke: &str) -> El {
    El::G {
        cls: "lini-block".into(),
        style: format!("fill: {}; stroke: {}; stroke-width: 1", fill, stroke),
        tx: 0.0,
        ty: 0.0,
        title: None,
        inner: vec![rect(-5.0, -5.0, 10.0, 10.0, 2.0)],
        kids: vec![],
    }
}

fn swatch(s: &Series) -> El {
    let h = hue(s.index);
    match s.kind {
        Kind::Bars => {
            let (fill, stroke, _) = bar_colors(s, 0);
            match stroke {
                Some(st) => swatch_outlined(&fill, &st),
                None => swatch_filled(&fill),
            }
        }
        Kind::Area => {
            let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{}-soft)", h));
            let st = color_at(&s.stroke, 0).unwrap_or_else(|| deep_of(&fill));
            swatch_outlined(&fill, &st)
        }
        Kind::Line => {
            if s.stroke.is_some() {
                let c = series_line_color(s);
                swatch_outlined(&c, &c)
            } else {
                swatch_filled(&series_line_color(s))
            }
        }
        Kind::Dots => swatch_filled(&format!("var(--lini-{}-ink)", h)),
        Kind::Bubble => swatch_filled(&color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{})", h))),
    }
}

// The colour of a line series: stroke, else fill, else the walk's deep tier.
pub fn series_line_color(s: &Series) -> String {
    if let Some(c) = color_at(&s.stroke, 0) {
        return c;
    }
    if let Some(c) = color_at(&s.fill, 0) {
        return c;
    }
    format!("var(--lini-{}-deep)", hue(s.index))
}

pub fn line_style(color: &str, s: &Series) -> String {
    let mut st = format!("stroke: {}", color);
    if let Some(w) = s.stroke_width {
        st.push_str(&format!("; stroke-width: {}", f4(w)));
    }
    if let Some(ss) = &s.stroke_style {
        if ss != "solid" {
            if let Some(d) = crate::style::dasharray(ss, s.stroke_width.unwrap_or(2.0)) {
                st.push_str(&format!("; stroke-dasharray: {}", d));
            }
        }
    }
    st
}

// (fill, stroke or None for no outline, stroke width) of bar k.
pub fn bar_colors(s: &Series, k: usize) -> (String, Option<String>, f64) {
    let h = hue(s.index);
    let fill = match &s.fill {
        Some(v) if crate::style::single_term(v).map(|t| matches!(t, Term::Var(n, _) if n == "fill")).unwrap_or(false) => format!("var(--lini-{}-soft)", h),
        _ => color_at(&s.fill, k).unwrap_or_else(|| format!("var(--lini-{}-soft)", h)),
    };
    let none = s.stroke.as_ref().and_then(|v| crate::style::ident_of(v)) == Some("none");
    if none {
        return (fill, None, 0.0);
    }
    let stroke = color_at(&s.stroke, k).unwrap_or_else(|| deep_of(&fill));
    (fill, Some(stroke), 2.0)
}

// The drawn path through the points for a curve style.
pub fn curve_points(pts: &[(f64, f64)], curve: &str, horiz: bool) -> Vec<(f64, f64)> {
    match curve {
        "step" => {
            let mut out = Vec::new();
            for (k, p) in pts.iter().enumerate() {
                if k == 0 {
                    out.push(*p);
                } else {
                    let prev = pts[k - 1];
                    if horiz {
                        out.push((prev.0, p.1));
                    } else {
                        out.push((p.0, prev.1));
                    }
                    out.push(*p);
                }
            }
            out
        }
        "smooth" => smooth(pts),
        _ => pts.to_vec(),
    }
}

// Monotone cubic through the points, 16 samples per segment.
pub fn smooth(pts: &[(f64, f64)]) -> Vec<(f64, f64)> {
    let n = pts.len();
    if n < 3 {
        return pts.to_vec();
    }
    let mut sl = vec![0.0; n - 1];
    let mut hs = vec![0.0; n - 1];
    for k in 0..n - 1 {
        hs[k] = pts[k + 1].0 - pts[k].0;
        sl[k] = if hs[k] != 0.0 { (pts[k + 1].1 - pts[k].1) / hs[k] } else { 0.0 };
    }
    let mut m = vec![0.0; n];
    m[0] = sl[0];
    m[n - 1] = sl[n - 2];
    for k in 1..n - 1 {
        let (s0, s1) = (sl[k - 1], sl[k]);
        if s0 * s1 <= 0.0 {
            m[k] = 0.0;
        } else {
            let (h0, h1) = (hs[k - 1], hs[k]);
            let p = (s0 * h1 + s1 * h0) / (h0 + h1);
            m[k] = (s0.signum() + s1.signum()) * s0.abs().min(s1.abs()).min(0.5 * p.abs());
        }
    }
    let mut out = vec![pts[0]];
    for k in 0..n - 1 {
        let (x0, y0) = pts[k];
        let (x1, y1) = pts[k + 1];
        let h = x1 - x0;
        let c1 = (x0 + h / 3.0, y0 + m[k] * h / 3.0);
        let c2 = (x1 - h / 3.0, y1 - m[k + 1] * h / 3.0);
        for j in 1..=16 {
            let t = j as f64 / 16.0;
            let u = 1.0 - t;
            let x = u * u * u * x0 + 3.0 * u * u * t * c1.0 + 3.0 * u * t * t * c2.0 + t * t * t * x1;
            let y = u * u * u * y0 + 3.0 * u * u * t * c1.1 + 3.0 * u * t * t * c2.1 + t * t * t * y1;
            out.push((x, y));
        }
    }
    out
}

