// Pie and donut charts.

use super::cart::{legend_row, swatch_outlined};
use super::model::*;
use super::scale::*;
use super::*;
use crate::compile::Ctx;
use crate::diag::Diag;

pub fn draw(ctx: &Ctx, ch: &Chart, w: f64, h: f64) -> Result<Drawing, Diag> {
    let _ = ctx;
    let mut flags = Flags::default();
    let g = ch.gap;
    let (cl, cr, ct, cb) = (-w / 2.0, w / 2.0, -h / 2.0, h / 2.0);
    let named: Vec<usize> = (0..ch.slices.len()).filter(|&k| ch.slices[k].name.is_some()).collect();
    let legend = named.len() >= 2;
    let mut region_top = ct + 8.0;
    let mut title_y = 0.0;
    if ch.title.is_some() {
        title_y = region_top + 10.5;
        region_top += 18.0 + g;
    }
    let region_bottom = if legend { cb - 16.4 - g } else { cb - 8.0 };
    let cy = (region_top + region_bottom) / 2.0;
    let cx = 0.0;
    let r = ((region_bottom - region_top) / 2.0).min((cr - cl - 16.0) / 2.0) + 2.0;
    let rin = ch.hole * r;
    let total: f64 = ch.slices.iter().map(|s| s.value).sum();
    let show_tips = ch.tooltip != "none";
    let mut els = Vec::new();
    let mut hits: Vec<(f64, f64, String)> = Vec::new();
    let mut a0 = -90.0f64;
    for (k, s) in ch.slices.iter().enumerate() {
        let frac = if total > 0.0 { s.value / total } else { 0.0 };
        let a1 = a0 + frac * 360.0;
        let n = ((frac * 64.0 - 1e-9).ceil() as usize).max(1);
        let mut pts = Vec::new();
        for j in 0..=n {
            let a = (a0 + (a1 - a0) * j as f64 / n as f64).to_radians();
            pts.push((cx + r * a.cos(), cy + r * a.sin()));
        }
        if rin > 0.0 {
            for j in (0..=n).rev() {
                let a = (a0 + (a1 - a0) * j as f64 / n as f64).to_radians();
                pts.push((cx + rin * a.cos(), cy + rin * a.sin()));
            }
        } else {
            pts.push((cx, cy));
        }
        let h_ = hue(k);
        let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{}-soft)", h_));
        let stroke = color_at(&s.stroke, 0).unwrap_or_else(|| deep_of(&fill));
        let pct = format!("{}%", fixed0(frac * 100.0));
        let val = fmt_value(s.value, ch.format.as_ref());
        let tt = match &s.name {
            Some(nm) => format!("{}: {} ({})", nm, val, pct),
            None => format!("{} ({})", val, pct),
        };
        let hk = hits.len();
        flags.poly = true;
        let cls = if show_tips { format!("lini-hit-{} ", hk) } else { String::new() };
        els.push(poly_el(
            &cls,
            &pts,
            &format!("fill: {}; stroke: {}; stroke-width: 2; opacity: 1", fill, stroke),
            if show_tips { Some(tt.clone()) } else { None },
        ));
        if show_tips {
            let (bx, by) = bbox_center(&pts);
            hits.push((bx, by, tt));
        }
        a0 = a1;
    }
    if let Some(t) = &ch.title {
        flags.title = true;
        els.push(text_el("lini-chart-title", 0.0, title_y, "", t));
    }
    if legend {
        flags.legend = true;
        let items: Vec<(String, El)> = named
            .iter()
            .map(|&k| {
                let s = &ch.slices[k];
                let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{}-soft)", hue(k)));
                let stroke = color_at(&s.stroke, 0).unwrap_or_else(|| deep_of(&fill));
                (s.name.clone().unwrap(), swatch_outlined(&fill, &stroke))
            })
            .collect();
        legend_row(&mut els, items, cb - 10.8);
    }
    if show_tips && !hits.is_empty() {
        flags.tip = true;
        flags.text = true;
        flags.hits = hits.len();
        for (k, (x, y, t)) in hits.iter().enumerate() {
            els.push(tip_el(k, *x, *y, t, [cl, ct, cr, cb]));
        }
    }
    Ok(Drawing { els, flags, bbox: None })
}

fn fixed0(v: f64) -> String {
    format!("{}", v.round() as i64)
}

pub fn bbox_center(pts: &[(f64, f64)]) -> (f64, f64) {
    let mut b = [f64::INFINITY, f64::INFINITY, f64::NEG_INFINITY, f64::NEG_INFINITY];
    for &(x, y) in pts {
        b[0] = b[0].min(x);
        b[1] = b[1].min(y);
        b[2] = b[2].max(x);
        b[3] = b[3].max(y);
    }
    ((b[0] + b[2]) / 2.0, (b[1] + b[3]) / 2.0)
}

// Radial (spider) charts: categories around a circle, values outward.

use super::cart::{legend_row, line_style, series_line_color, swatch_filled, swatch_outlined, VAxis};
use super::model::*;
use super::pie::bbox_center;
use super::scale::*;
use super::*;
use crate::compile::Ctx;
use crate::diag::Diag;

pub fn draw(ctx: &Ctx, ch: &Chart, w: f64, h: f64) -> Result<Drawing, Diag> {
    let _ = ctx;
    let mut flags = Flags::default();
    let c = ch.clearance;
    let g = ch.gap;
    let (cl, cr, ct, cb) = (-w / 2.0, w / 2.0, -h / 2.0, h / 2.0);
    let cats: Vec<String> = match &ch.categories {
        Some(c) => c.clone(),
        None => {
            let n = ch.series.iter().map(|s| s.vals.len()).max().unwrap_or(0);
            (1..=n).map(|k| k.to_string()).collect()
        }
    };
    let n = cats.len().max(1);
    let named: Vec<usize> = (0..ch.series.len()).filter(|&k| ch.series[k].name.is_some()).collect();
    let legend = named.len() >= 2;
    let mut region_top = ct + 8.0;
    let mut title_y = 0.0;
    if ch.title.is_some() {
        title_y = region_top + 10.5;
        region_top += 18.0 + g;
    }
    let region_bottom = if legend { cb - 16.4 - g } else { cb - 8.0 };
    let cy = (region_top + region_bottom) / 2.0;
    let cx = 0.0;
    let half = ((region_bottom - region_top) / 2.0).min((cr - cl - 16.0) / 2.0);
    let rr = half - c - 8.8;
    // the value axis
    let ax = ch.axes.iter().position(|_| true);
    let mut vals = Vec::new();
    for s in &ch.series {
        vals.extend(s.vals.iter().cloned());
    }
    let va = value_axis_radial(ch, ax, &vals);
    let rad = |v: f64| -> f64 { va.frac(v) * rr };
    let ang = |k: usize| -> f64 { (-90.0 + 360.0 * k as f64 / n as f64).to_radians() };
    let pt = |k: usize, r: f64| -> (f64, f64) {
        let a = ang(k);
        (cx + r * a.cos(), cy + r * a.sin())
    };
    let mut els = Vec::new();
    let grid = "stroke: var(--lini-grid); stroke-width: 1";
    if va.gridlines {
        for &t in &va.ticks {
            let r = rad(t);
            if r <= 1e-9 {
                continue;
            }
            let mut pts: Vec<(f64, f64)> = (0..n).map(|k| pt(k, r)).collect();
            pts.push(pts[0]);
            flags.line = true;
            els.push(path_el(&pts, grid));
        }
        for k in 0..n {
            let p = pt(k, rr);
            flags.line = true;
            els.push(line_el(cx, cy, p.0, p.1, grid));
        }
    }
    let show_tips = ch.tooltip != "none";
    let mut hits: Vec<(f64, f64, String)> = Vec::new();
    let fmt = ch.format.clone();
    let tip_text = |s: &Series, k: usize, v: f64| -> String {
        let val = fmt_value(v, fmt.as_ref());
        let cat = cats.get(k).cloned().unwrap_or_default();
        match &s.name {
            Some(nm) => format!("{} · {}: {}", cat, nm, val),
            None => format!("{}: {}", cat, val),
        }
    };
    let mut order: Vec<usize> = Vec::new();
    for kind in [Kind::Area, Kind::Bars, Kind::Line, Kind::Dots] {
        for (k, s) in ch.series.iter().enumerate() {
            if s.kind == kind {
                order.push(k);
            }
        }
    }
    let bar_series: Vec<usize> = (0..ch.series.len()).filter(|&k| ch.series[k].kind == Kind::Bars).collect();
    let nb = bar_series.len().max(1) as f64;
    let mut bars_done = false;
    for &si in &order {
        let s = &ch.series[si];
        let hn = hue(s.index);
        match s.kind {
            Kind::Area | Kind::Line => {
                let pts: Vec<(f64, f64)> = s.vals.iter().enumerate().map(|(k, v)| pt(k, rad(*v))).collect();
                let mut closed = pts.clone();
                if let Some(f) = pts.first() {
                    closed.push(*f);
                }
                if s.kind == Kind::Area {
                    let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{}-soft)", hn));
                    flags.poly = true;
                    els.push(poly_el("", &pts, &format!("fill: {}; stroke: none; stroke-width: 0; opacity: 0.82", fill), None));
                    let lc = color_at(&s.stroke, 0).unwrap_or_else(|| deep_of(&fill));
                    flags.line = true;
                    els.push(path_el(&closed, &line_style(&lc, s)));
                } else {
                    let color = series_line_color(s);
                    flags.line = true;
                    els.push(path_el(&closed, &line_style(&color, s)));
                }
            }
            Kind::Bars => {
                if bars_done {
                    continue;
                }
                bars_done = true;
                let sector = 360.0 / n as f64;
                let group = 0.72 * sector;
                let slot = group / nb;
                for k in 0..n {
                    for (bk, &bsi) in bar_series.iter().enumerate() {
                        let s = &ch.series[bsi];
                        let v = match s.vals.get(k) {
                            Some(v) => *v,
                            None => continue,
                        };
                        let mid = -90.0 + sector * k as f64;
                        let a0 = mid - group / 2.0 + slot * bk as f64;
                        let a1 = a0 + slot;
                        let r = rad(v);
                        let segs = (((a1 - a0) / 360.0 * 64.0 - 1e-9).ceil() as usize).max(1);
                        let mut pts = Vec::new();
                        for j in 0..=segs {
                            let a = (a0 + (a1 - a0) * j as f64 / segs as f64).to_radians();
                            pts.push((cx + r * a.cos(), cy + r * a.sin()));
                        }
                        pts.push((cx, cy));
                        let fill = color_at(&s.fill, k).unwrap_or_else(|| format!("var(--lini-{}-soft)", hue(s.index)));
                        let stroke = color_at(&s.stroke, k).unwrap_or_else(|| deep_of(&fill));
                        let tt = tip_text(s, k, v);
                        let hk = hits.len();
                        flags.poly = true;
                        let cls = if show_tips { format!("lini-hit-{} ", hk) } else { String::new() };
                        els.push(poly_el(
                            &cls,
                            &pts,
                            &format!("fill: {}; stroke: {}; stroke-width: 2; opacity: 1", fill, stroke),
                            if show_tips { Some(tt.clone()) } else { None },
                        ));
                        if show_tips {
                            let (bx, by) = bbox_center(&pts);
                            hits.push((bx, by, tt));
                        }
                    }
                }
            }
            _ => {}
        }
    }
    let muted = "fill: var(--lini-muted)";
    for (k, name) in cats.iter().enumerate() {
        let a = ang(k);
        let (dx, dy) = (a.cos(), a.sin());
        let d = dx.abs() * tw(name) / 2.0 + dy.abs() * FS / 2.0;
        let dist = rr + c + d;
        flags.text = true;
        els.push(text_el("lini-chart-text", cx + dist * dx, cy + dist * dy, muted, name));
    }
    for (t, l) in va.ticks.iter().zip(va.labels.iter()) {
        let r = rad(*t);
        if r <= 1e-9 {
            continue;
        }
        flags.text = true;
        els.push(text_el("lini-chart-text", cx + c + tw(l) / 2.0, cy - r, muted, l));
    }
    if let Some(t) = &ch.title {
        flags.title = true;
        els.push(text_el("lini-chart-title", 0.0, title_y, "", t));
    }
    if legend {
        flags.legend = true;
        let items: Vec<(String, El)> = named
            .iter()
            .map(|&k| {
                let s = &ch.series[k];
                let hn = hue(s.index);
                let sw = match s.kind {
                    Kind::Line => {
                        if s.stroke.is_some() {
                            let col = series_line_color(s);
                            swatch_outlined(&col, &col)
                        } else {
                            swatch_filled(&series_line_color(s))
                        }
                    }
                    _ => {
                        let fill = color_at(&s.fill, 0).unwrap_or_else(|| format!("var(--lini-{}-soft)", hn));
                        let st = color_at(&s.stroke, 0).unwrap_or_else(|| deep_of(&fill));
                        swatch_outlined(&fill, &st)
                    }
                };
                (s.name.clone().unwrap(), sw)
            })
            .collect();
        legend_row(&mut els, items, cb - 10.8);
    }
    if show_tips && !hits.is_empty() {
        flags.tip = true;
        flags.text = true;
        flags.hits = hits.len();
        for (k, (x, y, t)) in hits.iter().enumerate() {
            els.push(tip_el(k, *x, *y, t, [cl, ct, cr, cb]));
        }
    }
    Ok(Drawing { els, flags, bbox: None })
}

fn value_axis_radial(ch: &Chart, ax: Option<usize>, vals: &[f64]) -> VAxis {
    let a = ax.map(|k| &ch.axes[k]);
    let (lo, hi, step) = match a.and_then(|a| a.range) {
        Some((l, h)) => {
            let s = match a.and_then(|a| a.step.clone()) {
                Some(StepSpec::Num(s)) if s > 0.0 => s,
                _ => nice_step((h - l).abs()),
            };
            (l, h, s)
        }
        None => {
            let mut mn = 0.0f64;
            let mut mx = 0.0f64;
            for &v in vals {
                mn = mn.min(v);
                mx = mx.max(v);
            }
            let s = match a.and_then(|a| a.step.clone()) {
                Some(StepSpec::Num(s)) if s > 0.0 => s,
                _ => nice_step(mx - mn),
            };
            let (l, h) = if mx == mn { (0.0, 1.0) } else { nice_domain(mn, mx, s) };
            (l, h, s)
        }
    };
    let mut ticks = ticks_in(lo, hi, step);
    if let Some(t) = a.and_then(|a| a.ticks.clone()) {
        ticks = t;
    }
    let unit = a.map(|a| a.unit.clone()).unwrap_or_default();
    let f = a.and_then(|a| a.format.clone()).or_else(|| ch.format.clone());
    let labels = ticks.iter().map(|v| format!("{}{}", fmt_tick(*v, step, f.as_ref()), unit)).collect();
    VAxis {
        ax,
        right: false,
        lo,
        hi,
        log: false,
        ticks,
        labels,
        title: a.and_then(|a| a.title.clone()),
        gridlines: a.map(|a| a.gridlines).unwrap_or(true),
    }
}

