#!/usr/bin/env python3
# Fit the smooth-curve arithmetic against original outputs.
import itertools, re

def f4(v):
    s = '%.4f' % v
    if '.' in s:
        s = s.rstrip('0').rstrip('.')
    if s == '-0':
        s = '0'
    return s

cases = []
# (pl, pr, pt, pb, lo, hi, vals, expected polyline string)
hero = open('/tmp/chart/h1.svg').read()
polys = re.findall(r'<polyline points="([^"]*)"', hero)
# web (split into two) and app
web = polys[3].split() + polys[4].split()[1:]  # merge
app = polys[5].split()
cases.append((-165.192, 178.0, -94.0, 82.8, 0, 60, [16, 18, 22, 28, 35, 42], web))
cases.append((-165.192, 178.0, -94.0, 82.8, 0, 60, [8, 14, 20, 30, 42, 58], app))
curve = open('/tmp/chart/orig/prop_curve.svg').read()
cp = re.findall(r'<polyline points="([^"]*)"', curve)[0].split()
cases.append((-162.284, 168.0, -102.0, 81.2, 0, 8, [4, 8, 6], cp))

def sg(v):
    return (v > 0) - (v < 0)

def ys(pl, pr, pt, pb, lo, hi, vals, yv):
    out = []
    for v in vals:
        if yv == 0:
            out.append(pb - ((v - lo) / (hi - lo)) * (pb - pt))
        elif yv == 1:
            out.append(pb - (v - lo) * (pb - pt) / (hi - lo))
        elif yv == 2:
            out.append(pb + ((v - lo) / (hi - lo)) * (pt - pb))
        elif yv == 3:
            f = (v - lo) / (hi - lo)
            out.append(pb * (1 - f) + pt * f)
    return out

def tangents(X, Y, tv):
    n = len(X)
    h = [X[k + 1] - X[k] for k in range(n - 1)]
    s = [(Y[k + 1] - Y[k]) / h[k] for k in range(n - 1)]
    m = [0.0] * n
    if tv == 0:
        m[0] = s[0]; m[-1] = s[-1]
    elif tv == 1:
        m[0] = s[0]; m[-1] = s[-1]
    for k in range(1, n - 1):
        s0, s1 = s[k - 1], s[k]
        h0, h1 = h[k - 1], h[k]
        if tv == 0:
            if s0 * s1 <= 0:
                m[k] = 0.0
            else:
                p = (s0 * h1 + s1 * h0) / (h0 + h1)
                m[k] = (sg(s0) + sg(s1)) * min(abs(s0), abs(s1), 0.5 * abs(p))
        elif tv == 1:
            # Fritsch-Carlson harmonic mean
            if s0 * s1 <= 0:
                m[k] = 0.0
            else:
                w1 = 2 * h1 + h0; w2 = h1 + 2 * h0
                m[k] = (w1 + w2) / (w1 / s0 + w2 / s1)
    return m, h

def evals(x0, y0, x1, y1, m0, m1, t, ev):
    hh = x1 - x0
    u = 1 - t
    if ev == 0:
        c1 = y0 + m0 * hh / 3; c2 = y1 - m1 * hh / 3
        return u * u * u * y0 + 3 * u * u * t * c1 + 3 * u * t * t * c2 + t * t * t * y1
    if ev == 1:
        h00 = 2 * t**3 - 3 * t**2 + 1; h10 = t**3 - 2 * t**2 + t; h01 = -2 * t**3 + 3 * t**2; h11 = t**3 - t**2
        return h00 * y0 + h10 * hh * m0 + h01 * y1 + h11 * hh * m1
    if ev == 2:
        c1 = y0 + m0 * hh / 3; c2 = y1 - m1 * hh / 3
        a = y0 + (c1 - y0) * t; b = c1 + (c2 - c1) * t; c = c2 + (y1 - c2) * t
        d = a + (b - a) * t; e = b + (c - b) * t
        return d + (e - d) * t
    if ev == 3:
        c1 = y0 + m0 * hh / 3; c2 = y1 - m1 * hh / 3
        a = u * y0 + t * c1; b = u * c1 + t * c2; c = u * c2 + t * y1
        d = u * a + t * b; e = u * b + t * c
        return u * d + t * e
    if ev == 4:
        t2 = t * t; t3 = t2 * t
        return (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * m0 * hh + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * m1 * hh
    if ev == 5:
        c1 = y0 + m0 * hh / 3.0; c2 = y1 - m1 * hh / 3.0
        return y0 * u**3 + c1 * 3 * u**2 * t + c2 * 3 * u * t**2 + y1 * t**3
    if ev == 6:
        # cubic coefficients
        dy = y1 - y0
        a = m0 * hh; b = m1 * hh
        c3 = a + b - 2 * dy; c2 = 3 * dy - 2 * a - b
        return ((c3 * t + c2) * t + a) * t + y0
    if ev == 7:
        dx = hh
        c1 = y0 + dx * m0 / 3; c2 = y1 - dx * m1 / 3
        return (1 - t)**3 * y0 + 3 * (1 - t)**2 * t * c1 + 3 * (1 - t) * t**2 * c2 + t**3 * y1

for yv in range(4):
    for tv in range(2):
        for ev in range(8):
            for tm in range(2):
                bad = 0
                for (pl, pr, pt, pb, lo, hi, vals, exp) in cases:
                    n = len(vals)
                    X = [pl + (pr - pl) * ((k + 0.5) / n) for k in range(n)]
                    Y = ys(pl, pr, pt, pb, lo, hi, vals, yv)
                    m, h = tangents(X, Y, tv)
                    got = [(X[0], Y[0])]
                    for k in range(n - 1):
                        for j in range(1, 17):
                            t = j / 16 if tm == 0 else j * 0.0625
                            got.append((X[k] + h[k] * t, evals(X[k], Y[k], X[k + 1], Y[k + 1], m[k], m[k + 1], t, ev)))
                    gs = ['%s,%s' % (f4(x), f4(y)) for x, y in got]
                    for a, b in zip(gs, exp):
                        if a != b:
                            bad += 1
                print(yv, tv, ev, tm, 'bad', bad)

