#!/usr/bin/env python3
# Simulate run-splitting of clipped polylines under different y-scale formulas.
import math

def clip_runs(pts, rc):
    runs = []
    cur = []
    for k in range(1, len(pts)):
        x0, y0 = pts[k - 1]
        x1, y1 = pts[k]
        dx = x1 - x0
        dy = y1 - y0
        t0, t1 = 0.0, 1.0
        ok = True
        for p, q in [(-dx, x0 - rc[0]), (dx, rc[2] - x0), (-dy, y0 - rc[1]), (dy, rc[3] - y0)]:
            if p == 0:
                if q < 0:
                    ok = False
                    break
            else:
                r = q / p
                if p < 0:
                    if r > t1:
                        ok = False; break
                    elif r > t0:
                        t0 = r
                else:
                    if r < t0:
                        ok = False; break
                    elif r < t1:
                        t1 = r
        if not ok:
            if len(cur) >= 2:
                runs.append(cur)
            cur = []
            continue
        q0 = (x0 + t0 * dx, y0 + t0 * dy)
        q1 = (x0 + t1 * dx, y0 + t1 * dy)
        if cur and cur[-1] == q0:
            cur.append(q1)
        else:
            if len(cur) >= 2:
                runs.append(cur)
            cur = [q0, q1]
    if len(cur) >= 2:
        runs.append(cur)
    return runs

def yform(kind, v, lo, hi, pt, pb):
    f = (v - lo) / (hi - lo)
    if kind == 0:
        return pb - f * (pb - pt)
    if kind == 1:
        return pt + (1 - f) * (pb - pt)
    if kind == 2:
        return pb + f * (pt - pb)
    if kind == 3:
        return pt + (hi - v) / (hi - lo) * (pb - pt)
    if kind == 4:
        return pb - (v - lo) * (pb - pt) / (hi - lo)
    if kind == 5:
        return pb + (v - lo) * (pt - pb) / (hi - lo)

def xcat(k, n, pl, pr):
    return pl + (pr - pl) * ((k + 0.5) / n)

def case_runs(kind, vals, lo, hi, pl, pr, pt, pb):
    n = len(vals)
    pts = [(xcat(k, n, pl, pr), yform(kind, v, lo, hi, pt, pb)) for k, v in enumerate(vals)]
    runs = clip_runs(pts, [pl, pt, pr, pb])
    return [len(r) for r in runs]

cases = [
    # name, vals, lo, hi, pl, pr, pt, pb, expected run lengths
    ('title 10,50,1', [10, 50, 1, 1, 1, 1], 0, 60, -165.192, 178.0, -94.0, 106.2, [2, 5]),
    ('title 10,50,2', [10, 50, 2, 2, 2, 2], 0, 60, -165.192, 178.0, -94.0, 106.2, [2, 2, 4]),
    ('area_two p', [1, 3, 2], 0, 3, -162.284, 168.0, -102.0, 57.8, [3]),
    ('area_two q', [2, 1, 3], 0, 3, -162.284, 168.0, -102.0, 57.8, [3]),
]
for kind in range(6):
    res = []
    for (name, vals, lo, hi, pl, pr, pt, pb, exp) in cases:
        got = case_runs(kind, vals, lo, hi, pl, pr, pt, pb)
        res.append('%s:%s%s' % (name, got, '' if got == exp else '!!'))
    print(kind, ' | '.join(res))

