fn value_axis(ch: &Chart, ax: Option<usize>, right: bool, vals: &[f64]) -> Result<VAxis, Diag> {
    let a = ax.map(|k| &ch.axes[k]);
    let log = a.map(|a| a.log).unwrap_or(false);
