// ------------------------------------------------------------ calendar ticks

#[derive(Clone, Copy, PartialEq, Debug)]
pub enum TUnit {
    Minute,
    Hour,
    Day,
    Week,
    Month,
    Year,
}

pub fn tunit_of(s: &str) -> Option<TUnit> {
    Some(match s {
        "minute" | "minutes" => TUnit::Minute,
        "hour" | "hours" => TUnit::Hour,
        "day" | "days" => TUnit::Day,
        "week" | "weeks" => TUnit::Week,
        "month" | "months" => TUnit::Month,
        "year" | "years" => TUnit::Year,
        _ => return None,
    })
}

fn tunit_days(u: TUnit) -> f64 {
    match u {
        TUnit::Minute => 1.0 / 1440.0,
        TUnit::Hour => 1.0 / 24.0,
        TUnit::Day => 1.0,
        TUnit::Week => 7.0,
        TUnit::Month => 365.25 / 12.0,
        TUnit::Year => 365.25,
    }
}

const AUTO_TSTEPS: &[(TUnit, i64)] = &[
    (TUnit::Minute, 1),
    (TUnit::Minute, 2),
    (TUnit::Minute, 5),
    (TUnit::Minute, 10),
    (TUnit::Minute, 15),
    (TUnit::Minute, 30),
    (TUnit::Hour, 1),
    (TUnit::Hour, 2),
    (TUnit::Hour, 3),
    (TUnit::Hour, 6),
    (TUnit::Hour, 12),
    (TUnit::Day, 1),
    (TUnit::Day, 2),
    (TUnit::Week, 1),
    (TUnit::Week, 2),
    (TUnit::Month, 1),
    (TUnit::Month, 2),
    (TUnit::Month, 3),
    (TUnit::Month, 6),
    (TUnit::Year, 1),
    (TUnit::Year, 2),
    (TUnit::Year, 5),
    (TUnit::Year, 10),
    (TUnit::Year, 20),
    (TUnit::Year, 50),
    (TUnit::Year, 100),
    (TUnit::Year, 200),
    (TUnit::Year, 500),
    (TUnit::Year, 1000),
];

pub fn auto_tstep(span: f64) -> (TUnit, i64) {
    for &(u, n) in AUTO_TSTEPS {
        if span / (n as f64 * tunit_days(u)) <= 5.0 + 1e-9 {
            return (u, n);
        }
    }
    (TUnit::Year, 1000)
}

pub fn time_ticks(lo: f64, hi: f64, u: TUnit, n: i64) -> Vec<f64> {
    let (lo, hi) = if lo <= hi { (lo, hi) } else { (hi, lo) };
    let n = n.max(1);
    let eps = 1e-9;
    let mut out = Vec::new();
    match u {
        TUnit::Minute | TUnit::Hour | TUnit::Day => {
            let per = match u {
                TUnit::Minute => 1440.0,
                TUnit::Hour => 24.0,
                _ => 1.0,
            };
            // in whole units since the epoch
            let a = (lo * per - eps).ceil() as i64;
            let b = (hi * per + eps).floor() as i64;
            let mut k = a.div_euclid(n) * n;
            if k < a {
                k += n;
            }
            while k <= b && out.len() < 10000 {
                out.push(k as f64 / per);
                k += n;
            }
        }
        TUnit::Week => {
            let step = 7 * n;
            let a = (lo - eps).ceil() as i64;
            let b = (hi + eps).floor() as i64;
            let mut k = 4 + (a - 4).div_euclid(step) * step;
            if k < a {
                k += step;
            }
            while k <= b && out.len() < 10000 {
                out.push(k as f64);
                k += step;
            }
        }
        TUnit::Month => {
            let (y0, m0, d0) = civil_from_days(lo.floor() as i64);
            let (mut y, mut m) = (y0, m0);
            let first = days_from_civil(y0, m0, 1) as f64;
            if !(d0 == 1 && (lo - first).abs() < eps) {
                m += 1;
                if m > 12 {
                    m = 1;
                    y += 1;
                }
            }
            for _ in 0..10000 {
                let d = days_from_civil(y, m, 1) as f64;
                if d > hi + eps {
                    break;
                }
                out.push(d);
                m += n;
                while m > 12 {
                    m -= 12;
                    y += 1;
                }
            }
        }
        TUnit::Year => {
            let (y0, _, _) = civil_from_days(lo.floor() as i64);
            let mut y = y0.div_euclid(n) * n;
            for _ in 0..10000 {
                let d = days_from_civil(y, 1, 1) as f64;
                if d > hi + eps {
                    break;
                }
                if d >= lo - eps {
                    out.push(d);
                }
                y += n;
            }
        }
    }
    if out.is_empty() {
        out = vec![lo, hi];
    }
    out
}

pub fn time_label(v: f64, u: TUnit) -> String {
    let p = match u {
        TUnit::Minute | TUnit::Hour => "hour",
        TUnit::Day | TUnit::Week => "day",
        TUnit::Month => "month",
        TUnit::Year => "year",
    };
    fmt_date_preset(v, p)
}
