#!/usr/bin/env python3
import json, math, itertools
exec(open('/tmp/chart/clipsim.py').read().split('def yform')[0])  # clip_runs

def nice_step(span):
    p = 10 ** (math.floor(math.log10(span / 5)) - 1)
    for _ in range(40):
        for m in (1, 2, 5):
            s = m * p
            if span / s <= 5 + 1e-9:
                return s
        p *= 10
    return p

def snap(q):
    return round(q) if abs(q - round(q)) < 1e-9 else q

def sg(v):
    return (v > 0) - (v < 0)

def tangents(X, Y):
    n = len(X)
    h = [X[k + 1] - X[k] for k in range(n - 1)]
    s = [(Y[k + 1] - Y[k]) / h[k] for k in range(n - 1)]
    m = [0.0] * n
    m[0] = s[0]; m[-1] = s[-1]
    for k in range(1, n - 1):
        s0, s1 = s[k - 1], s[k]
        if s0 * s1 <= 0:
            m[k] = 0.0
        else:
            h0, h1 = h[k - 1], h[k]
            p = (s0 * h1 + s1 * h0) / (h0 + h1)
            m[k] = (sg(s0) + sg(s1)) * min(abs(s0), abs(s1), 0.5 * abs(p))
    return m, h

def samples(X, Y, xv, yv):
    m, h = tangents(X, Y)
    out = [(X[0], Y[0])]
    n = len(X)
    for k in range(n - 1):
        x0, y0, x1, y1 = X[k], Y[k], X[k + 1], Y[k + 1]
        hh = x1 - x0
        c1 = y0 + m[k] * hh / 3
        c2 = y1 - m[k + 1] * hh / 3
        cx1 = x0 + hh / 3
        cx2 = x1 - hh / 3
        for j in range(1, 17):
            t = j / 16
            u = 1 - t
            if xv == 0:
                x = x0 + hh * t
            elif xv == 1:
                x = x0 + (x1 - x0) * t
            elif xv == 2:
                x = u * x0 + t * x1
            elif xv == 3:
                x = u * u * u * x0 + 3 * u * u * t * cx1 + 3 * u * t * t * cx2 + t * t * t * x1
            elif xv == 4:
                x = x0 * u ** 3 + cx1 * 3 * u ** 2 * t + cx2 * 3 * u * t ** 2 + x1 * t ** 3
            if yv == 0:
                y = u * u * u * y0 + 3 * u * u * t * c1 + 3 * u * t * t * c2 + t * t * t * y1
            elif yv == 1:
                y = y0 * u ** 3 + c1 * 3 * u ** 2 * t + c2 * 3 * u * t ** 2 + y1 * t ** 3
            elif yv == 2:
                t2 = t * t; t3 = t2 * t
                y = (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * hh * m[k] + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * hh * m[k + 1]
            out.append((x, y))
    return out

cases = json.load(open('/tmp/chart/smoothruns.json'))
eps = 1e-9
for xv in range(5):
    for yv in range(3):
        bad = 0
        for c in cases:
            xs, ys = c['xs'], c['ys']
            pl, pr, pt, pb = c['pl'], c['pr'], c['pt'], c['pb']
            lo, hi = min(xs), max(xs)
            mx = max(ys)
            st = nice_step(mx)
            yhi = snap(mx / st)
            yhi = math.ceil(yhi) * st
            X = [pl + (x - lo) / (hi - lo) * (pr - pl) for x in xs]
            Y = [pb - ((y - 0) / (yhi - 0)) * (pb - pt) for y in ys]
            pts = samples(X, Y, xv, yv)
            runs = [len(r) for r in clip_runs(pts, [pl - eps, pt - eps, pr + eps, pb + eps])]
            if runs != c['runs']:
                bad += 1
        print(xv, yv, 'bad', bad, 'of', len(cases))

