import subprocess
props = {
    'data': '1, 2', 'categories': '"a"', 'hole': '0.5', 'curve': 'smooth', 'value': '1', 'labels': '"a"', 'at': '1', 'axis': 'x',
    'bars': 'stacked', 'baseline': '1', 'fn': '(x)', 'gridlines': 'none', 'range': '0 1', 'side': 'left', 'step': '1', 'ticks': '1, 2',
    'unit': '"k"', 'format': 'decimal 1', 'tooltip': 'always', 'scale': 'log', 'marker': 'dot', 'samples': '5', 'clearance': '3', 'direction': 'radial',
}
hosts = ['|box|', '|line| { points: 0 0, 10 10; }', '|chart| { categories: "a"; } [ |bars| { data: 1; X } ]', '|chart| { categories: "a"; X } [ |bars| { data: 1; } ]', '|pie| { X } [ |slice| { value: 1; } ]', '|pie| [ |slice| { value: 1; X } ]', '|chart| { categories: "a"; } [ |axis| { side: left; X }; |bars| { data: 1; } ]', '|chart| { categories: "a"; } [ |line| { data: 1; X } ]']
for pname, pval in props.items():
    row = []
    for h in hosts:
        decl = '%s: %s;' % (pname, pval)
        if 'X' in h:
            src = h.replace('X', decl)
        elif h.startswith('|line|'):
            src = h.replace('}', decl + ' }')
        else:
            src = '%s { %s }' % (h, decl)
        open('/tmp/chart/t1/mn.lini', 'w').write(src + '\n')
        r = subprocess.run(['/workspace/executable', 'mn.lini'], capture_output=True, cwd='/tmp/chart/t1')
